"use client";

import React from 'react';
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    Download,
    X,
    Calendar,
    CheckSquare,
    Sparkles,
    Gavel,
    Star,
    FileText,
    ArrowRight,
    ShieldCheck,
    BookOpen,
} from 'lucide-react';
import { ActionKitItem, RelatedLaw } from '../types';

const isRelatedLawObject = (law: string | RelatedLaw): law is RelatedLaw => {
    return typeof law === "object" && law !== null && "name" in law;
};

// Contextual usage tips based on document tag/type
const USAGE_GUIDE: Record<string, { about: string; tips: string[] }> = {
    "근로계약서": {
        about: "근로계약서는 사용자(기업)와 근로자 간의 근로조건을 서면으로 명시하는 핵심 법률 문서입니다. 근로기준법 제17조에 따라 반드시 서면으로 교부해야 하며, 미교부 시 500만원 이하의 벌금이 부과될 수 있습니다.",
        tips: [
            "근로계약서는 반드시 2부를 작성하여 1부는 근로자에게 교부하세요.",
            "임금, 소정근로시간, 휴일, 연차유급휴가 등 필수 기재사항을 빠뜨리지 마세요.",
            "수습기간을 둘 경우 기간과 조건을 명확히 기재해야 합니다.",
            "계약기간, 업무내용, 근무장소 변경 시 반드시 근로자 동의를 받으세요."
        ]
    },
    "임대차": {
        about: "상가건물 임대차보호법에 따라 보호받는 임대차계약 관련 서류입니다. 환산보증금 기준, 계약갱신요구권(10년), 권리금 보호 등 상가 임차인의 핵심 권리를 이해하고 활용할 수 있습니다.",
        tips: [
            "확정일자를 반드시 받아두세요 (대항력 + 우선변제권 확보).",
            "환산보증금을 계산하여 상가임대차보호법 적용 여부를 확인하세요.",
            "계약갱신요구권은 최초 계약일로부터 10년까지 행사 가능합니다.",
            "권리금 회수기회 보호: 임대인이 정당한 사유 없이 방해하면 손해배상 청구 가능합니다."
        ]
    },
    "default": {
        about: "본 문서는 창업 및 사업 운영 과정에서 필수적으로 활용되는 실무 서류입니다. 관련 법령의 요건을 충족하도록 작성되었으며, 실제 사용 시에는 사업의 특성에 맞게 내용을 검토·수정하여 활용하시기 바랍니다.",
        tips: [
            "서류 작성 전 최신 법령 개정사항을 반드시 확인하세요.",
            "중요한 계약이나 신고는 전문가(변호사, 세무사 등)의 검토를 권장합니다.",
            "원본은 안전하게 보관하고, 사본을 별도로 관리하세요.",
            "작성일자와 서명/날인을 빠뜨리지 않도록 주의하세요."
        ]
    }
};

function getUsageGuide(item: ActionKitItem): { about: string; tips: string[] } {
    // Try to match by name keyword
    for (const key of Object.keys(USAGE_GUIDE)) {
        if (key === "default") continue;
        if (item.name?.includes(key)) {
            return USAGE_GUIDE[key];
        }
    }
    return USAGE_GUIDE["default"];
}

interface ActionKitDetailModalProps {
    item: ActionKitItem;
    onClose: () => void;
    onDownload: (path: string, name: string, id?: number) => void;
    onNavigateToLaw?: (lawTitle: string) => void;
    onToggleBookmark: (item: ActionKitItem, e: React.MouseEvent) => void;
    isBookmarked: boolean;
    checkedItems: Record<string, boolean>;
    onToggleChecklist: (kitIdentifier: string, checkItem: string) => void;
    getKitProgress: (kit: ActionKitItem) => { checked: number; total: number; percentage: number } | null;
}

export const ActionKitDetailModal = ({
    item,
    onClose,
    onDownload,
    onNavigateToLaw,
    onToggleBookmark,
    isBookmarked,
    checkedItems,
    onToggleChecklist,
    getKitProgress,
}: ActionKitDetailModalProps) => {
    const guide = getUsageGuide(item);
    const kitIdentifier = (item as any).id || item.name;
    const progress = getKitProgress(item);

    return (
        <div
            className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200"
            onClick={onClose}
        >
            <div
                className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-hidden animate-in zoom-in-95 slide-in-from-bottom-4 duration-300 flex flex-col"
                onClick={(e) => e.stopPropagation()}
            >
                {/* ── Header ── */}
                <div className="relative p-6 pb-5 bg-gradient-to-br from-slate-50 to-[#36a4f2]/5 border-b border-slate-100">
                    <div className="flex justify-between items-start">
                        <div className="flex-1 pr-4">
                            <div className="flex items-center gap-2 mb-3">
                                <Badge className="bg-[#36a4f2]/10 text-[#36a4f2] hover:bg-[#36a4f2]/20 border-none text-xs font-black uppercase">
                                    {item.tag || '[실무]'}
                                </Badge>
                                <Badge variant="secondary" className="text-[10px] font-bold text-slate-400">
                                    {item.type}
                                </Badge>
                                {item.dday && (
                                    <Badge className="bg-orange-500 hover:bg-orange-600 text-[10px] font-bold">
                                        {item.dday}
                                    </Badge>
                                )}
                            </div>
                            <h2 className="text-xl font-bold text-slate-900 leading-tight">
                                {item.name}
                            </h2>
                            <p className="text-sm text-slate-500 mt-2 leading-relaxed">
                                {item.summary}
                            </p>
                        </div>
                        <div className="flex items-center gap-2 shrink-0">
                            <button
                                onClick={(e) => onToggleBookmark(item, e)}
                                className={`p-2 rounded-full transition-all ${isBookmarked
                                    ? 'text-yellow-400 bg-yellow-50 hover:bg-yellow-100'
                                    : 'text-slate-300 bg-white hover:text-yellow-400 hover:bg-yellow-50'
                                    } border border-slate-100 shadow-sm`}
                                title={isBookmarked ? '서랍장에서 제거' : '서랍장에 추가'}
                            >
                                <Star className={`w-5 h-5 ${isBookmarked ? 'fill-current' : ''}`} />
                            </button>
                            <button
                                onClick={onClose}
                                className="p-2 rounded-full text-slate-400 hover:text-slate-600 bg-white border border-slate-100 shadow-sm hover:bg-slate-50 transition-colors"
                            >
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                    </div>

                    {/* Progress Bar (if applicable) */}
                    {progress && (
                        <div className="mt-4 flex items-center gap-3">
                            <div className="flex-1 bg-white rounded-full h-2 overflow-hidden border border-slate-100">
                                <div
                                    className={`h-2 rounded-full transition-all duration-700 ${progress.percentage === 100 ? 'bg-emerald-500' : 'bg-[#36a4f2]'}`}
                                    style={{ width: `${progress.percentage}%` }}
                                />
                            </div>
                            <span className={`text-xs font-black tabular-nums ${progress.percentage === 100 ? 'text-emerald-500' : 'text-slate-500'}`}>
                                {progress.percentage}%
                            </span>
                        </div>
                    )}
                </div>

                {/* ── Body ── */}
                <div className="flex-1 overflow-y-auto p-6 space-y-6">

                    {/* Section 1 : About This Document */}
                    <div className="space-y-3">
                        <h3 className="font-bold text-sm text-slate-800 flex items-center gap-2">
                            <div className="w-6 h-6 rounded-lg bg-[#36a4f2]/10 flex items-center justify-center">
                                <BookOpen className="w-3.5 h-3.5 text-[#36a4f2]" />
                            </div>
                            이 서류는 어떤 문서인가요?
                        </h3>
                        <div className="text-sm text-slate-600 leading-relaxed bg-slate-50 p-4 rounded-2xl border border-slate-100">
                            {guide.about}
                        </div>
                    </div>

                    {/* Section 2 : Usage Tips */}
                    <div className="space-y-3">
                        <h3 className="font-bold text-sm text-slate-800 flex items-center gap-2">
                            <div className="w-6 h-6 rounded-lg bg-emerald-50 flex items-center justify-center">
                                <ShieldCheck className="w-3.5 h-3.5 text-emerald-500" />
                            </div>
                            실무 활용 팁
                        </h3>
                        <div className="space-y-2">
                            {guide.tips.map((tip, i) => (
                                <div key={i} className="flex items-start gap-3 p-3 rounded-xl bg-emerald-50/50 border border-emerald-100/50">
                                    <span className="text-emerald-500 font-black text-xs mt-0.5 bg-emerald-100 w-5 h-5 rounded-full flex items-center justify-center shrink-0">
                                        {i + 1}
                                    </span>
                                    <span className="text-sm text-slate-700 leading-relaxed">{tip}</span>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Section 3 : Compliance Checklist */}
                    {item.complianceChecklist && item.complianceChecklist.length > 0 && (
                        <div className="space-y-3">
                            <div className="flex justify-between items-center">
                                <h3 className="font-bold text-sm text-slate-800 flex items-center gap-2">
                                    <div className="w-6 h-6 rounded-lg bg-blue-50 flex items-center justify-center">
                                        <CheckSquare className="w-3.5 h-3.5 text-[#36a4f2]" />
                                    </div>
                                    사용 전 필수 체크리스트
                                </h3>
                                {progress && (
                                    <span className={`text-xs font-black ${progress.percentage === 100 ? 'text-emerald-500' : 'text-slate-400'}`}>
                                        {progress.checked}/{progress.total} 완료
                                    </span>
                                )}
                            </div>
                            <div className="space-y-2">
                                {item.complianceChecklist.map((checkItem, i) => {
                                    const key = `${kitIdentifier}_${checkItem}`;
                                    const isChecked = !!checkedItems[key];
                                    return (
                                        <label key={i} className={`flex items-start gap-3 p-3 rounded-xl border transition-all cursor-pointer group ${isChecked
                                            ? 'border-emerald-300 bg-emerald-50'
                                            : 'border-slate-100 hover:border-[#36a4f2]/30 hover:bg-[#36a4f2]/5'
                                            }`}>
                                            <input
                                                type="checkbox"
                                                className="mt-0.5 w-4 h-4 rounded border-slate-300 text-emerald-500 focus:ring-emerald-500 cursor-pointer"
                                                checked={isChecked}
                                                onChange={() => onToggleChecklist(kitIdentifier, checkItem)}
                                            />
                                            <span className={`text-sm leading-tight transition-all ${isChecked ? 'text-emerald-700 font-medium line-through opacity-70' : 'text-slate-600 group-hover:text-slate-900'}`}>
                                                {checkItem}
                                            </span>
                                        </label>
                                    );
                                })}
                            </div>
                        </div>
                    )}

                    {/* Section 4 : Highlights */}
                    {(item as any).highlights?.length > 0 && (
                        <div className="space-y-3">
                            <h3 className="font-bold text-sm text-slate-800 flex items-center gap-2">
                                <div className="w-6 h-6 rounded-lg bg-amber-50 flex items-center justify-center">
                                    <Sparkles className="w-3.5 h-3.5 text-amber-500" />
                                </div>
                                핵심 포인트
                            </h3>
                            <div className="space-y-2">
                                {(item as any).highlights.map((hl: any, i: number) => (
                                    <div key={hl.id || i} className="flex items-start gap-2.5 p-3 rounded-xl bg-amber-50 border border-amber-100">
                                        <span className="text-amber-500 font-bold text-sm mt-0.5">⭐</span>
                                        <span className="text-sm text-slate-700 leading-relaxed">{hl.content}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Section 5 : Related Laws Cross-Navigation */}
                    {item.relatedLaws && item.relatedLaws.length > 0 && (
                        <div className="space-y-3">
                            <h3 className="font-bold text-sm text-slate-800 flex items-center gap-2">
                                <div className="w-6 h-6 rounded-lg bg-violet-50 flex items-center justify-center">
                                    <Gavel className="w-3.5 h-3.5 text-violet-500" />
                                </div>
                                관련 법령 가이드
                            </h3>
                            <div className="space-y-2">
                                {item.relatedLaws.map((law, i) => {
                                    const name = isRelatedLawObject(law) ? law.name : law;
                                    const summary = isRelatedLawObject(law) ? law.summary : null;
                                    return (
                                        <button
                                            key={i}
                                            onClick={() => {
                                                onNavigateToLaw?.(name);
                                                onClose();
                                            }}
                                            className="w-full flex items-center gap-3 p-3.5 rounded-2xl border border-violet-100 bg-violet-50/50 hover:bg-violet-100/60 hover:border-violet-200 transition-all group text-left"
                                        >
                                            <div className="w-8 h-8 rounded-xl bg-white border border-violet-100 flex items-center justify-center shrink-0 shadow-sm group-hover:shadow transition-shadow">
                                                <Gavel className="w-4 h-4 text-violet-500" />
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <p className="text-sm font-bold text-violet-800 group-hover:text-violet-900 transition-colors truncate">
                                                    {name}
                                                </p>
                                                {summary && (
                                                    <p className="text-xs text-violet-500 mt-0.5 line-clamp-1">{summary}</p>
                                                )}
                                            </div>
                                            <ArrowRight className="w-4 h-4 text-violet-300 group-hover:text-violet-500 transition-colors shrink-0 group-hover:translate-x-0.5 transform" />
                                        </button>
                                    );
                                })}
                            </div>
                            <p className="text-[10px] text-slate-400 pl-1">
                                클릭하면 법령 가이드 탭으로 이동하여 해당 법률의 핵심 내용을 확인할 수 있습니다.
                            </p>
                        </div>
                    )}
                </div>

                {/* ── Footer Action Bar ── */}
                <div className="p-5 border-t border-slate-100 bg-slate-50/80 flex items-center justify-between gap-3">
                    <div className="flex items-center gap-2 text-slate-400">
                        <Calendar className="w-3.5 h-3.5" />
                        <span className="text-xs font-medium">Updated: 2026.02</span>
                    </div>
                    <div className="flex items-center gap-3">
                        <Button
                            variant="outline"
                            className="rounded-full border-slate-200 hover:bg-slate-100"
                            onClick={onClose}
                        >
                            닫기
                        </Button>
                        <Button
                            className="bg-[#36a4f2] hover:bg-[#258bd1] gap-2 rounded-full px-6 shadow-lg shadow-[#36a4f2]/20"
                            onClick={() => {
                                onDownload(item.path, item.name, (item as any).id);
                            }}
                        >
                            <Download className="w-4 h-4" />
                            원본 다운로드
                        </Button>
                    </div>
                </div>
            </div>
        </div>
    );
};

"use client";

import React, { useState, useEffect } from 'react';
import JSZip from 'jszip';
import { saveAs } from 'file-saver';
import { useActionKit } from '../hooks/useActionKit';
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    FolderOpen,
    Search,
    Download,
    Info,
    Calendar,
    Layers,
    Briefcase,
    TrendingUp,
    Sparkles,
    Gavel,
    CheckSquare,
    Package,
    Users,
    Building,
    Eye,
    Star,
    X,
    Trash2,
    LucideIcon,
    History,
} from 'lucide-react';
import { ActionKitItem, RelatedLaw } from '../types';
import { apiClient } from '@/lib/api-client';
import { ActionKitDetailModal } from './ActionKitDetailModal';

const STARTER_PACKS = [
    {
        id: "hire",
        title: "직원 채용 필수 팩",
        icon: Users,
        color: "text-purple-500",
        bg: "bg-purple-100",
        keywords: ["근로계약서", "취업규칙", "비밀유지"]
    },
    {
        id: "office",
        title: "사무실 계약 팩",
        icon: Building,
        color: "text-[#36a4f2]",
        bg: "bg-[#36a4f2]/10",
        keywords: ["임대차", "화재안전", "건축물"]
    },
    {
        id: "invest",
        title: "투자 유치 준비 팩",
        icon: Package,
        color: "text-orange-500",
        bg: "bg-orange-100",
        keywords: ["주주", "정관", "이사회"]
    }
];

const CATEGORY_ICONS: Record<string, LucideIcon> = {
    all: Layers,
    legal: Gavel,
    tax: TrendingUp,
    hr: Briefcase,
    grant: Sparkles,
};

const CATEGORY_COLORS: Record<string, string> = {
    all: 'bg-slate-100 text-slate-600',
    legal: 'bg-[#36a4f2]/10 text-[#36a4f2]',
    tax: 'bg-green-100 text-green-600',
    hr: 'bg-purple-100 text-purple-600',
    grant: 'bg-orange-100 text-orange-600',
};

const isRelatedLawObject = (law: string | RelatedLaw): law is RelatedLaw => {
    return typeof law === "object" && law !== null && "name" in law;
};

interface ActionKitLibraryViewProps {
    initialSearch?: string;
    onNavigateToLaw?: (lawTitle: string) => void;
}

export const ActionKitLibraryView = ({ initialSearch = "", onNavigateToLaw }: ActionKitLibraryViewProps) => {
    const { data, loading, error } = useActionKit();
    const [selectedCategory, setSelectedCategory] = useState<string>("all");
    const [searchQuery, setSearchQuery] = useState(initialSearch);
    const [activeStarterPack, setActiveStarterPack] = useState<string | null>(null);
    const [selectedTag, setSelectedTag] = useState<string>("all");
    const [previewKit, setPreviewKit] = useState<ActionKitItem | null>(null);
    const [detailItem, setDetailItem] = useState<ActionKitItem | null>(null);
    const [recentItems, setRecentItems] = useState<ActionKitItem[]>([]);
    const [isHistoryOpen, setIsHistoryOpen] = useState(false);


    useEffect(() => {
        setSelectedTag("all");
    }, [selectedCategory, searchQuery, activeStarterPack]);

    const [checkedItems, setCheckedItems] = useState<Record<string, boolean>>({});
    const [bookmarkedItems, setBookmarkedItems] = useState<Record<string, ActionKitItem>>({});
    const [isDrawerOpen, setIsDrawerOpen] = useState(false);
    const [isZipping, setIsZipping] = useState(false);

    // Onboarding State
    const [isOnboardingOpen, setIsOnboardingOpen] = useState(false);
    const [onboardingStep, setOnboardingStep] = useState<1 | 2>(1);
    const [selectedPackId, setSelectedPackId] = useState<string | null>(null);

    useEffect(() => {
        const hasSeenOnboarding = localStorage.getItem('actionkit_onboarding_shown');
        if (!hasSeenOnboarding) {
            setIsOnboardingOpen(true);
        }
    }, []);

    useEffect(() => {
        const storedChecklists = localStorage.getItem('actionkit_checklists');
        if (storedChecklists) {
            try { setCheckedItems(JSON.parse(storedChecklists)); } catch (e) { }
        }
        const storedBookmarks = localStorage.getItem('actionkit_bookmarks');
        if (storedBookmarks) {
            try { setBookmarkedItems(JSON.parse(storedBookmarks)); } catch (e) { }
        }
        const storedRecents = localStorage.getItem('actionkit_recents');
        if (storedRecents) {
            try { setRecentItems(JSON.parse(storedRecents)); } catch (e) { }
        }
    }, []);

    const handleItemClick = (item: ActionKitItem) => {
        setDetailItem(item);
        setRecentItems(prev => {
            const filtered = prev.filter(i => i.name !== item.name);
            const next = [item, ...filtered].slice(0, 5); // Keep up to 5 items
            localStorage.setItem('actionkit_recents', JSON.stringify(next));
            return next;
        });
    };

    const toggleBookmark = (kit: ActionKitItem, e: React.MouseEvent) => {
        e.stopPropagation();
        const identifier = (kit as any).id || kit.name;
        const newBookmarks = { ...bookmarkedItems };
        if (newBookmarks[identifier]) {
            delete newBookmarks[identifier];
        } else {
            newBookmarks[identifier] = kit;
        }
        setBookmarkedItems(newBookmarks);
        localStorage.setItem('actionkit_bookmarks', JSON.stringify(newBookmarks));
    };

    const handleBulkDownload = async () => {
        setIsZipping(true);
        try {
            const zip = new JSZip();
            const items = Object.values(bookmarkedItems);

            await Promise.all(items.map(async (item) => {
                const itemId = (item as any).id;
                let blob: Blob | null = null;
                if (itemId) {
                    try {
                        const res = await apiClient.get(`/actionkits/items/${itemId}/download`, { responseType: 'blob' });
                        blob = new Blob([res.data]);
                    } catch (apiErr: any) {
                        if (apiErr.response?.status !== 404) throw apiErr;
                    }
                }

                if (!blob && item.path) {
                    let finalPath = item.path;
                    if (finalPath.startsWith('library/resources/')) {
                        finalPath = finalPath.replace('library/resources/', 'actionkits/files/');
                    }
                    if (finalPath.startsWith('http')) {
                        const res = await fetch(finalPath);
                        blob = await res.blob();
                    } else {
                        const baseURL = process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:8000/api/v1";
                        const res = await fetch(`${baseURL}/${finalPath}`);
                        blob = await res.blob();
                    }
                }

                if (blob) {
                    const filename = (item as any).files?.[0]?.original_filename || `${item.name}.${(item as any).ext || 'pdf'}`;
                    zip.file(filename, blob);
                }
            }));

            const content = await zip.generateAsync({ type: 'blob' });
            saveAs(content, '나만의_액션키트_보관함.zip');
        } catch (error) {
            console.error(error);
            alert("다운로드 중 오류가 발생했습니다.");
        } finally {
            setIsZipping(false);
        }
    };

    const toggleChecklist = (kitId: number | string, itemText: string) => {
        const key = `${kitId}_${itemText}`;
        const newChecked = { ...checkedItems, [key]: !checkedItems[key] };
        setCheckedItems(newChecked);
        localStorage.setItem('actionkit_checklists', JSON.stringify(newChecked));
    };

    const handleAddPackToDrawer = () => {
        if (!selectedPackId || !data) return;
        const pack = STARTER_PACKS.find(p => p.id === selectedPackId);
        if (!pack) return;

        const newBookmarks = { ...bookmarkedItems };
        let addedCount = 0;

        Object.values(data).forEach(cat => {
            cat.items.forEach(item => {
                const isMatch = pack.keywords.some(keyword =>
                    item.name.toLowerCase().includes(keyword.toLowerCase()) ||
                    item.summary.toLowerCase().includes(keyword.toLowerCase()) ||
                    (item.tag && item.tag.toLowerCase() === keyword.toLowerCase())
                );
                if (isMatch) {
                    const identifier = (item as any).id || item.name;
                    if (!newBookmarks[identifier]) {
                        newBookmarks[identifier] = item;
                        addedCount++;
                    }
                }
            });
        });

        if (addedCount > 0) {
            setBookmarkedItems(newBookmarks);
            localStorage.setItem('actionkit_bookmarks', JSON.stringify(newBookmarks));
        }

        setIsOnboardingOpen(false);
        localStorage.setItem('actionkit_onboarding_shown', 'true');
        setTimeout(() => setIsDrawerOpen(true), 300);
    };

    const handleOnboardingSkip = () => {
        setIsOnboardingOpen(false);
        localStorage.setItem('actionkit_onboarding_shown', 'true');
    };

    const getKitProgress = (kit: ActionKitItem) => {
        if (!kit.complianceChecklist || kit.complianceChecklist.length === 0) return null;
        const kitIdentifier = (kit as any).id || kit.name;
        const total = kit.complianceChecklist.length;
        const checked = kit.complianceChecklist.filter(item => checkedItems[`${kitIdentifier}_${item}`]).length;
        const percentage = Math.round((checked / total) * 100);
        return { total, checked, percentage };
    };

    if (loading) return <div className="p-8 text-center text-slate-500">액션 키트 라이브러리를 불러오는 중...</div>;
    if (error) return <div className="p-8 text-center text-red-500">{error}</div>;
    if (!data) return null;

    const categories = Object.entries(data);
    const currentCategory = data[selectedCategory];

    const handleDownload = async (path: string, filename: string, itemId?: number) => {
        try {
            let success = false;
            if (itemId) {
                try {
                    // Use authenticated API download for DB-managed files
                    const res = await apiClient.get(`/actionkits/items/${itemId}/download`, { responseType: 'blob' });
                    const url = window.URL.createObjectURL(new Blob([res.data]));
                    const link = document.createElement('a');
                    link.href = url;
                    link.setAttribute('download', filename);
                    document.body.appendChild(link);
                    link.click();
                    link.remove();
                    window.URL.revokeObjectURL(url);
                    success = true;
                } catch (apiErr: any) {
                    if (apiErr.response?.status !== 404) throw apiErr;
                }
            }

            if (!success && path) {
                // Fallback for legacy path-based files
                const baseURL = process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:8000/api/v1";
                let finalPath = path;
                if (path.startsWith('library/resources/')) {
                    finalPath = path.replace('library/resources/', 'actionkits/files/');
                }
                const url = finalPath.startsWith('http') ? finalPath : `${baseURL}/${finalPath}`;
                const link = document.createElement('a');
                link.href = url;
                link.target = "_blank";
                link.download = filename;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
            }
        } catch (err) {
            console.error('Download failed:', err);
            alert('다운로드 중 오류가 발생했습니다.');
        }
    };

    const filteredItems = Object.values(data).flatMap(cat =>
        cat.items.map(item => ({ ...item, categoryTitle: cat.title }))
    ).filter(item => {
        const isMatch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            item.summary.toLowerCase().includes(searchQuery.toLowerCase());

        if (activeStarterPack) {
            const pack = STARTER_PACKS.find(p => p.id === activeStarterPack);
            if (pack) {
                return pack.keywords.some(keyword =>
                    item.name.toLowerCase().includes(keyword.toLowerCase()) ||
                    item.summary.toLowerCase().includes(keyword.toLowerCase())
                );
            }
        }

        return isMatch;
    });

    const baseDisplayItems = (searchQuery || activeStarterPack) ? filteredItems : (currentCategory?.items || []);
    const availableTags = Array.from(new Set(baseDisplayItems.map(item => item.tag).filter(Boolean))).sort();
    const displayItems = selectedTag === "all" ? baseDisplayItems : baseDisplayItems.filter(item => item.tag === selectedTag);

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            {/* Header with Search */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-900">액션 키트 라이브러리</h2>
                    <p className="text-sm text-slate-500 mt-1">
                        {searchQuery ? `'${searchQuery}' 검색 결과` : "실무에 즉시 투입 가능한 문서와 도구들을 확인하세요."}
                    </p>
                </div>
                <div className="flex items-center gap-2 w-full md:w-auto">
                    <div className="relative w-full md:w-64">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                        <input
                            type="text"
                            placeholder="키트 검색..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-full text-sm focus:ring-2 focus:ring-[#36a4f2]/20 transition-all outline-none"
                        />
                    </div>
                    <Button
                        onClick={() => {
                            setOnboardingStep(1);
                            setSelectedPackId(null);
                            setIsOnboardingOpen(true);
                        }}
                        variant="outline"
                        className="rounded-full border-[#36a4f2]/30 text-[#36a4f2] hover:bg-[#36a4f2]/5 whitespace-nowrap h-10 px-4"
                    >
                        🎁 맞춤 팩 받기
                    </Button>

                    {/* Recent Items Dropdown */}
                    <div className="relative">
                        <Button
                            variant="outline"
                            onClick={() => setIsHistoryOpen(!isHistoryOpen)}
                            className="rounded-full border-slate-200 text-slate-600 hover:bg-slate-50 h-10 px-4 gap-2 whitespace-nowrap"
                        >
                            <History className="w-4 h-4" />
                            <span className="hidden sm:inline">최근 본 액션키트</span>
                            {recentItems.length > 0 && (
                                <span className="bg-slate-100 text-slate-500 text-[10px] font-bold px-1.5 py-0.5 rounded-full min-w-[1.25rem] text-center">
                                    {recentItems.length}
                                </span>
                            )}
                        </Button>

                        {isHistoryOpen && (
                            <>
                                <div className="fixed inset-0 z-40" onClick={() => setIsHistoryOpen(false)} />
                                <div className="absolute right-0 mt-2 w-72 bg-white rounded-2xl shadow-xl shadow-slate-200/50 border border-slate-100 z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                                    <div className="p-3 border-b border-slate-50 bg-slate-50/50 flex justify-between items-center">
                                        <h4 className="text-xs font-bold text-slate-700 flex items-center gap-1.5">
                                            <History className="w-3.5 h-3.5 text-slate-400" />
                                            최근 열람한 문서
                                        </h4>
                                        {recentItems.length > 0 && (
                                            <button onClick={() => { setRecentItems([]); localStorage.setItem('actionkit_recents', '[]'); }} className="text-[10px] text-slate-400 hover:text-red-500 font-medium px-2 py-1 rounded hover:bg-red-50 transition-colors">
                                                기록 지우기
                                            </button>
                                        )}
                                    </div>
                                    <div className="max-h-64 overflow-y-auto">
                                        {recentItems.length === 0 ? (
                                            <div className="p-6 text-center text-slate-400 text-xs">
                                                열람한 문서 기록이 없습니다.
                                            </div>
                                        ) : (
                                            <div className="p-2 space-y-1">
                                                {recentItems.map((item, i) => (
                                                    <button
                                                        key={i}
                                                        onClick={() => { handleItemClick(item); setIsHistoryOpen(false); }}
                                                        className="w-full text-left p-2 hover:bg-[#36a4f2]/5 rounded-xl transition-colors group flex items-start gap-2.5 outline-none focus:bg-[#36a4f2]/5"
                                                    >
                                                        <div className="w-6 h-6 rounded bg-slate-100 flex items-center justify-center shrink-0 group-hover:bg-[#36a4f2]/10 transition-colors">
                                                            <FolderOpen className="w-3 h-3 text-slate-400 group-hover:text-[#36a4f2]" />
                                                        </div>
                                                        <div className="flex-1 min-w-0">
                                                            <p className="text-[11px] font-bold text-slate-700 truncate group-hover:text-[#36a4f2] transition-colors">
                                                                {item.name}
                                                            </p>
                                                            <p className="text-[9px] text-slate-400 truncate mt-0.5">
                                                                {item.tag || item.type}
                                                            </p>
                                                        </div>
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </>
                        )}
                    </div>

                    <Button
                        onClick={() => setIsDrawerOpen(true)}
                        className="rounded-full bg-yellow-50 hover:bg-yellow-100 border border-yellow-200 text-yellow-700 relative h-10 px-4 whitespace-nowrap"
                    >
                        <Star className={`w-4 h-4 mr-1 ${Object.keys(bookmarkedItems).length > 0 ? 'fill-yellow-500 text-yellow-500' : ''}`} />
                        서랍장
                        {Object.keys(bookmarkedItems).length > 0 && (
                            <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border-2 border-white shadow-sm">
                                {Object.keys(bookmarkedItems).length}
                            </span>
                        )}
                    </Button>
                </div>
            </div>

            {/* Category Cards (Only show if not searching or pack) */}
            {!searchQuery && !activeStarterPack && (
                <div className="grid grid-cols-2 lg:grid-cols-5 gap-4">
                    {categories.map(([id, category]) => {
                        const Icon = CATEGORY_ICONS[id] || FolderOpen;
                        const isSelected = selectedCategory === id;
                        return (
                            <button
                                key={id}
                                onClick={() => setSelectedCategory(id)}
                                className={`flex flex-col items-center p-4 rounded-2xl transition-all ${isSelected
                                    ? 'bg-[#36a4f2] text-white shadow-lg scale-105'
                                    : 'bg-white hover:bg-slate-50 border border-slate-100 text-slate-600'
                                    }`}
                            >
                                <div className={`w-10 h-10 rounded-full flex items-center justify-center mb-2 ${isSelected ? 'bg-white/20' : CATEGORY_COLORS[id] || 'bg-slate-100'
                                    }`}>
                                    <Icon className="w-5 h-5" />
                                </div>
                                <span className="text-xs font-bold whitespace-nowrap">{category.title.split(' ')[0]}</span>
                            </button>
                        );
                    })}
                </div>
            )}

            {/* Starter Packs UI and logic */}
            {!searchQuery && selectedCategory === "all" && (
                <div className="space-y-3 animate-in fade-in slide-in-from-bottom-4 duration-500 delay-100">
                    <h3 className="text-sm font-bold text-slate-700 flex items-center gap-2">
                        <Sparkles className="w-4 h-4 text-[#36a4f2]" />
                        스타터 팩 컬렉션
                    </h3>
                    <div className="flex flex-col md:flex-row gap-4">
                        {STARTER_PACKS.map(pack => {
                            const PIcon = pack.icon;
                            const isActive = activeStarterPack === pack.id;
                            return (
                                <button
                                    key={pack.id}
                                    onClick={() => {
                                        if (isActive) {
                                            setActiveStarterPack(null);
                                            setSearchQuery("");
                                        } else {
                                            setActiveStarterPack(pack.id);
                                            setSearchQuery(""); // Clear search to use starter pack filter
                                        }
                                    }}
                                    className={`flex-1 p-4 rounded-2xl border transition-all text-left group flex items-start justify-between ${isActive
                                        ? "bg-slate-900 border-slate-900 shadow-lg text-white"
                                        : `border-slate-200 hover:shadow-md bg-white`
                                        }`}
                                >
                                    <div>
                                        <div className={`w-8 h-8 rounded-full flex items-center justify-center mb-2 ${isActive ? 'bg-white/20' : pack.bg}`}>
                                            <PIcon className={`w-4 h-4 ${isActive ? 'text-white' : pack.color}`} />
                                        </div>
                                        <div className={`font-bold text-sm ${isActive ? 'text-white' : 'text-slate-800'}`}>
                                            {pack.title}
                                        </div>
                                        <div className={`text-[10px] mt-1 ${isActive ? 'text-slate-300' : 'text-slate-500'}`}>
                                            주요: {pack.keywords.join(', ')}
                                        </div>
                                    </div>
                                </button>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* Tag Filter Bar */}
            {availableTags.length > 0 && (
                <div className="flex flex-wrap items-center gap-2 py-2 animate-in fade-in slide-in-from-bottom-2 duration-300">
                    <button
                        onClick={() => setSelectedTag("all")}
                        className={`px-4 py-1.5 rounded-full text-[13px] font-bold transition-all ${selectedTag === "all" ? "bg-slate-800 text-white shadow-md" : "bg-slate-100 text-slate-500 hover:bg-slate-200"}`}
                    >
                        전체보기
                    </button>
                    {availableTags.map(tag => (
                        <button
                            key={tag as string}
                            onClick={() => setSelectedTag(tag as string)}
                            className={`px-4 py-1.5 rounded-full text-[13px] font-bold transition-all border ${selectedTag === tag ? "bg-[#36a4f2]/10 border-[#36a4f2] text-[#36a4f2] shadow-sm" : "bg-white border-slate-200 text-slate-500 hover:border-[#36a4f2]/50 hover:bg-[#36a4f2]/5 hover:text-[#36a4f2]"}`}
                        >
                            {tag as string}
                        </button>
                    ))}
                </div>
            )}

            {/* Kits Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {displayItems.length > 0 ? (
                    displayItems.map((item, index) => (
                        <Card key={`${item.name}-${index}`} className="group hover:border-[#36a4f2] transition-all duration-300 shadow-sm hover:shadow-md cursor-pointer flex flex-col justify-between overflow-hidden" onClick={() => handleItemClick(item)}>
                            <CardContent className="p-0 flex flex-col h-full">
                                <div className="p-6 pb-0">
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="flex items-center gap-2">
                                            <Badge variant="outline" className="text-[10px] font-black text-[#36a4f2] bg-[#36a4f2]/5 border-[#36a4f2]/10 uppercase py-0.5 px-2">
                                                {item.tag || '[실무]'}
                                            </Badge>
                                            {(item.name.includes("근로계약서") || item.name.includes("임대차") || item.name.includes("동업") || item.name.includes("주주") || item.name.includes("정관")) && (
                                                <Badge className="bg-gradient-to-r from-rose-500 to-orange-500 hover:from-rose-600 hover:to-orange-600 border-none px-1.5 py-0 h-4 text-[9px] font-black shadow-sm gap-1">
                                                    <span className="animate-pulse">🔥</span> HOT
                                                </Badge>
                                            )}
                                        </div>
                                        <div className="flex items-center gap-2">
                                            {item.dday && (
                                                <Badge className="bg-orange-500 hover:bg-orange-600 text-[10px] font-bold py-0 h-5">
                                                    {item.dday}
                                                </Badge>
                                            )}
                                            <Badge variant="secondary" className="text-[10px] font-bold text-slate-400 py-0 h-5">
                                                {item.type}
                                            </Badge>
                                            <button
                                                onClick={(e) => toggleBookmark(item, e)}
                                                className={`p-1 -mr-2 rounded-full transition-colors ${bookmarkedItems[(item as any).id || item.name] ? 'text-yellow-400 hover:text-yellow-500' : 'text-slate-200 hover:text-yellow-400'}`}
                                            >
                                                <Star className={`w-5 h-5 ${bookmarkedItems[(item as any).id || item.name] ? 'fill-current' : ''}`} />
                                            </button>
                                        </div>
                                    </div>
                                    <h4 className="font-bold text-slate-800 mb-2 group-hover:text-[#36a4f2] transition-colors leading-tight min-h-[2.5rem] line-clamp-2">
                                        {item.name}
                                    </h4>
                                    <p className="text-xs text-slate-400 mb-3 line-clamp-2 leading-relaxed">
                                        {item.summary}
                                    </p>
                                    {(() => {
                                        const progress = getKitProgress(item);
                                        if (!progress) return null;
                                        return (
                                            <div className="mb-3 space-y-1.5">
                                                <div className="flex justify-between items-end">
                                                    <span className="text-[10px] font-bold text-slate-500 flex items-center gap-1">
                                                        <CheckSquare className="w-3 h-3 text-emerald-500" /> 필수 체크리스트
                                                    </span>
                                                    <span className={`text-[10px] font-black ${progress.percentage === 100 ? 'text-emerald-500' : 'text-slate-400'}`}>
                                                        {progress.percentage}%
                                                    </span>
                                                </div>
                                                <div className="w-full bg-slate-100 rounded-full h-1.5 overflow-hidden">
                                                    <div
                                                        className={`h-1.5 rounded-full transition-all duration-500 ${progress.percentage === 100 ? 'bg-emerald-500' : 'bg-[#36a4f2]'}`}
                                                        style={{ width: `${progress.percentage}%` }}
                                                    />
                                                </div>
                                            </div>
                                        );
                                    })()}
                                    {(item as any).highlights?.length > 0 && (
                                        <div className="flex flex-wrap gap-1 mb-3">
                                            {(item as any).highlights.slice(0, 2).map((hl: any, i: number) => (
                                                <span key={hl.id || i} className="text-[10px] font-medium text-amber-700 bg-amber-50 border border-amber-100 px-2 py-0.5 rounded-full truncate max-w-[180px]">
                                                    ⭐ {hl.content}
                                                </span>
                                            ))}
                                            {(item as any).highlights.length > 2 && (
                                                <span className="text-[10px] text-slate-400 font-medium">+{(item as any).highlights.length - 2}개</span>
                                            )}
                                        </div>
                                    )}
                                </div>

                                <div className="mt-auto px-6 pb-6 space-y-4">
                                    <div className="pt-2 border-t border-slate-50">
                                        {item.relatedLaws && item.relatedLaws.length > 0 && (
                                            <div className="space-y-2">
                                                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-wider flex items-center gap-1">
                                                    <Gavel className="w-3 h-3" /> 관련 조문 및 해설
                                                </p>
                                                <div className="space-y-1.5">
                                                    {item.relatedLaws.map((law, i) => {
                                                        const name = isRelatedLawObject(law) ? law.name : law;
                                                        const summary = isRelatedLawObject(law) ? law.summary : null;
                                                        const snippet = isRelatedLawObject(law) ? law.snippet : null;

                                                        return (
                                                            <div key={i} className="group/law relative inline-block mr-2 mb-2">
                                                                <button onClick={(e) => {
                                                                    e.stopPropagation();
                                                                    onNavigateToLaw?.(name);
                                                                }} className="flex items-center gap-1.5 w-full text-left">
                                                                    <span className="text-[10px] font-bold text-[#36a4f2] bg-[#36a4f2]/5 px-1.5 py-0.5 rounded border border-[#36a4f2]/10 transition-colors group-hover/law:bg-[#36a4f2]/10">
                                                                        #{name}
                                                                    </span>
                                                                    {summary && (
                                                                        <span className="text-[10px] text-slate-500 line-clamp-1 flex-1 transition-colors group-hover/law:text-slate-700">
                                                                            {summary}
                                                                        </span>
                                                                    )}
                                                                </button>
                                                                {/* Simple Snippet implementation using CSS hover */}
                                                                {snippet && (
                                                                    <div className="absolute z-50 bottom-full left-0 mb-2 hidden w-64 p-3 bg-slate-900 border border-slate-800 text-slate-200 text-xs rounded-xl shadow-xl group-hover/law:block group-hover/law:animate-in group-hover/law:fade-in duration-200">
                                                                        <p className="font-bold text-[#36a4f2] mb-1">법령 스니펫 미리보기</p>
                                                                        <p className="leading-relaxed whitespace-pre-wrap">{snippet}</p>
                                                                    </div>
                                                                )}
                                                            </div>
                                                        );
                                                    })}
                                                </div>
                                            </div>
                                        )}
                                    </div>

                                    <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                                        <div className="flex items-center gap-2 text-slate-400">
                                            <Calendar className="w-3 h-3" />
                                            <span className="text-[10px] font-medium">Updated: 2026.02</span>
                                        </div>
                                        <Button
                                            size="sm"
                                            variant="outline"
                                            className="h-8 rounded-full border-slate-200 hover:bg-slate-50 gap-1.5 px-3"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                setPreviewKit(item);
                                            }}
                                        >
                                            <Eye className="w-3 h-3 text-slate-400" />
                                            <span className="text-[11px] font-bold text-slate-600">미리보기</span>
                                        </Button>
                                        <Button
                                            size="sm"
                                            className="h-8 rounded-full bg-[#36a4f2] hover:bg-[#258bd1] gap-1.5 px-4"
                                            onClick={(e) => {
                                                e.stopPropagation();
                                                handleDownload(item.path, item.name);
                                            }}
                                        >
                                            <Download className="w-3 h-3" />
                                            <span className="text-[11px] font-bold">다운로드</span>
                                        </Button>
                                    </div>
                                </div>
                            </CardContent>
                        </Card>
                    ))
                ) : (
                    <div className="col-span-full py-20 flex flex-col items-center justify-center text-slate-400">
                        <Info className="w-12 h-12 mb-4 opacity-20" />
                        <p className="text-lg font-bold">검색 결과가 없습니다.</p>
                        <p className="text-sm">다른 키워드로 다시 검색해 보세요.</p>
                    </div>
                )}
            </div>

            {/* Detail View Modal */}
            {(detailItem || previewKit) && (
                <ActionKitDetailModal
                    item={(detailItem || previewKit)!}
                    onClose={() => { setDetailItem(null); setPreviewKit(null); }}
                    onDownload={handleDownload}
                    onNavigateToLaw={onNavigateToLaw}
                    onToggleBookmark={toggleBookmark}
                    isBookmarked={!!bookmarkedItems[(detailItem || previewKit as any)?.id || (detailItem || previewKit)?.name]}
                    checkedItems={checkedItems}
                    onToggleChecklist={toggleChecklist}
                    getKitProgress={getKitProgress}
                />
            )}

            {/* Bookmark Drawer */}
            {isDrawerOpen && (
                <div className="fixed inset-0 z-50 flex mb-0 bg-slate-900/40 backdrop-blur-sm justify-end">
                    <div className="w-full max-w-sm h-full bg-white shadow-2xl animate-in slide-in-from-right duration-300 flex flex-col">
                        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-yellow-50/50">
                            <h3 className="font-bold flex items-center gap-2 text-slate-800">
                                <Star className="w-5 h-5 fill-yellow-400 text-yellow-500" />
                                나만의 서랍장
                            </h3>
                            <button onClick={() => setIsDrawerOpen(false)} className="p-2 text-slate-400 hover:text-slate-600 rounded-full hover:bg-slate-100">
                                <X className="w-5 h-5" />
                            </button>
                        </div>
                        <div className="flex-1 overflow-y-auto p-4 space-y-3">
                            {Object.values(bookmarkedItems).length === 0 ? (
                                <div className="py-20 text-center text-slate-400">
                                    <Star className="w-12 h-12 mx-auto mb-4 opacity-20" />
                                    <p className="text-sm font-bold">서랍장이 비어있습니다.</p>
                                    <p className="text-xs mt-2">필요한 키트에 ⭐️ 별을 눌러 담아보세요.</p>
                                </div>
                            ) : (
                                Object.values(bookmarkedItems).map((item, i) => (
                                    <div key={i} className="flex gap-3 bg-white border border-slate-100 p-3 rounded-xl shadow-sm relative group pr-10">
                                        <div className="w-8 h-8 rounded bg-slate-50 border border-slate-100 flex items-center justify-center flex-shrink-0">
                                            <FolderOpen className="w-4 h-4 text-slate-400" />
                                        </div>
                                        <div>
                                            <h4 className="font-bold text-sm text-slate-800 line-clamp-1">{item.name}</h4>
                                            <p className="text-[10px] text-slate-500 mt-1 line-clamp-1">{item.summary}</p>
                                        </div>
                                        <button
                                            onClick={(e) => toggleBookmark(item, e)}
                                            className="absolute right-3 top-1/2 -translate-y-1/2 p-2 text-slate-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
                                        >
                                            <Trash2 className="w-4 h-4" />
                                        </button>
                                    </div>
                                ))
                            )}
                        </div>
                        {Object.values(bookmarkedItems).length > 0 && (
                            <div className="p-4 border-t border-slate-100 bg-slate-50">
                                <Button
                                    className="w-full bg-[#36a4f2] hover:bg-[#258bd1] text-white font-bold h-12 rounded-xl"
                                    onClick={handleBulkDownload}
                                    disabled={isZipping}
                                >
                                    {isZipping ? '압축하는 중...' : `${Object.keys(bookmarkedItems).length}개 한 번에 ZIP 다운로드`}
                                </Button>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* Onboarding Modal */}
            {isOnboardingOpen && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm p-4">
                    <div className="bg-white rounded-3xl w-full max-w-lg shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
                        {/* Header */}
                        <div className="p-6 pb-0 flex justify-between items-start">
                            <div className="pr-8">
                                <h3 className="text-xl md:text-2xl font-bold text-slate-800 tracking-tight leading-tight">
                                    {onboardingStep === 1 ? "대표님, 지금 가장 고민되시는 단계가 어디인가요?" : "대표님을 위한 맞춤 스타터 팩이 준비되었습니다!"}
                                </h3>
                                <p className="text-slate-500 text-sm mt-2">
                                    {onboardingStep === 1
                                        ? "현재 상황에 꼭 맞는 필수 서류 세트를 즉시 추천해 드릴게요."
                                        : "버튼 한 번만 누르면 내 서랍장에 쏙! 일괄 다운로드도 가능합니다."}
                                </p>
                            </div>
                            <button onClick={handleOnboardingSkip} className="p-2 -my-2 -mx-2 text-slate-400 hover:text-slate-600 rounded-full hover:bg-slate-100 transition-colors shrink-0">
                                <X className="w-5 h-5" />
                            </button>
                        </div>

                        {/* Content */}
                        <div className="p-6">
                            {onboardingStep === 1 ? (
                                <div className="space-y-3">
                                    {STARTER_PACKS.map(pack => (
                                        <button
                                            key={pack.id}
                                            onClick={() => {
                                                setSelectedPackId(pack.id);
                                                setOnboardingStep(2);
                                            }}
                                            className={`w-full text-left p-4 rounded-2xl border-2 transition-all group flex items-center gap-4 ${selectedPackId === pack.id
                                                ? 'border-[#36a4f2] bg-[#36a4f2]/5 shadow-sm'
                                                : 'border-slate-100 hover:border-[#36a4f2]/30 hover:bg-slate-50'
                                                }`}
                                        >
                                            <div className={`w-12 h-12 rounded-xl flex items-center justify-center shrink-0 ${pack.bg} ${pack.color}`}>
                                                <pack.icon className="w-6 h-6" />
                                            </div>
                                            <div>
                                                <h4 className="font-bold text-slate-800 text-lg group-hover:text-[#36a4f2] transition-colors">{pack.title}</h4>
                                                <p className="text-xs text-slate-500 mt-1 line-clamp-1">포함 서류: {pack.keywords.join(', ')} 등</p>
                                            </div>
                                        </button>
                                    ))}
                                    <button
                                        onClick={handleOnboardingSkip}
                                        className="w-full text-center p-4 rounded-2xl border-2 border-transparent text-slate-400 hover:text-slate-600 hover:bg-slate-50 transition-colors text-sm font-medium mt-2"
                                    >
                                        ⚖️ 기타 / 나중에 혼자 둘러볼래요 (스킵)
                                    </button>
                                </div>
                            ) : (
                                <div className="space-y-6">
                                    {(() => {
                                        const pack = STARTER_PACKS.find(p => p.id === selectedPackId);
                                        if (!pack) return null;
                                        return (
                                            <div className="flex flex-col items-center py-6 text-center">
                                                <div className={`w-20 h-20 rounded-2xl flex items-center justify-center mb-4 ${pack.bg} ${pack.color}`}>
                                                    <pack.icon className="w-10 h-10" />
                                                </div>
                                                <h4 className="text-xl font-bold text-slate-800">
                                                    <span className={pack.color}>{pack.title}</span> 증정
                                                </h4>
                                                <div className="flex flex-wrap justify-center gap-2 mt-4">
                                                    {pack.keywords.map((kw, i) => (
                                                        <Badge key={i} variant="outline" className="bg-slate-50 border-slate-200 text-slate-600 font-medium">
                                                            {kw}
                                                        </Badge>
                                                    ))}
                                                </div>
                                            </div>
                                        );
                                    })()}
                                    <Button
                                        onClick={handleAddPackToDrawer}
                                        className="w-full h-14 rounded-2xl bg-[#36a4f2] hover:bg-[#258bd1] text-white font-bold text-lg shadow-lg shadow-[#36a4f2]/20 gap-2"
                                    >
                                        <Star className="w-5 h-5 fill-white" />
                                        내 서랍장에 모두 담기
                                    </Button>
                                    <button
                                        onClick={() => setOnboardingStep(1)}
                                        className="w-full text-center text-sm text-slate-400 hover:text-slate-600 underline underline-offset-4"
                                    >
                                        이전으로 돌아가기
                                    </button>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* Disclaimer */}
            <div className="mt-16 bg-slate-50/50 rounded-2xl p-6 md:p-8 border border-slate-100">
                <h5 className="text-xs font-bold text-slate-500 mb-3 tracking-tight">법적 면책 조항 (Disclaimer)</h5>
                <p className="text-[11px] leading-relaxed text-slate-400 break-keep">
                    본 조사자료는 고객의 창업에 정보를 제공할 목적으로 작성되었으며, 어떠한 경우에도 무단 복제 및 배포 될 수 없습니다.<br />
                    또한 본 자료에 수록된 내용은 당사가 신뢰할 만한 자료 및 정보로 얻어진 것이나, 그 정확성이나 완전성을 보장할 수 없으므로
                    창업자 자신의 판단과 책임하에 최종결정을 하시기 바랍니다.<br />
                    <span className="text-slate-500 font-medium mt-1 inline-block">따라서 어떠한 경우에도 본 자료는 고객의 창업의 결과에 대한 법적 책임소재의 증빙자료로 사용될 수 없습니다.</span>
                </p>
            </div>
        </div>
    );
};

"use client";

import React, { useState } from 'react';
import { useLawGuide } from '../hooks/useLawGuide';
import { useActionKit } from '../hooks/useActionKit';
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
    FileText,
    Search,
    Download,
    CheckCircle2,
    Info,
    Sparkles,
    FolderOpen,
    Eye,
    EyeOff
} from 'lucide-react';
import { LawItem, RelatedLaw, ActionKitItem } from '../types';
import { LawDetailPopup } from './LawDetailPopup';

type LawItemWithChapter = LawItem & { chapterTitle: string };

interface LawGuideViewProps {
    initialSearch?: string;
    onNavigateToKit?: (kitName: string) => void;
}

export const LawGuideView = ({ initialSearch = "", onNavigateToKit }: LawGuideViewProps) => {
    const { data, loading, error } = useLawGuide();
    const { data: kitsData } = useActionKit();
    const [activeChapter, setActiveChapter] = useState<string>("1");
    const [searchQuery, setSearchQuery] = useState(initialSearch);

    // Manage completed/read status (in-memory for demo, would be localStorage/DB in real app)
    const [completedItems, setCompletedItems] = useState<Set<string>>(new Set());
    const [selectedLaw, setSelectedLaw] = useState<LawItem | null>(null);

    const toggleItemCompletion = (e: React.MouseEvent, itemName: string) => {
        e.stopPropagation();
        setCompletedItems(prev => {
            const next = new Set(prev);
            if (next.has(itemName)) {
                next.delete(itemName);
            } else {
                next.add(itemName);
            }
            return next;
        });
    };

    const isRelatedLawObject = (law: string | RelatedLaw): law is RelatedLaw => {
        return typeof law === "object" && law !== null && "name" in law;
    };

    const getRelatedKits = (lawName: string) => {
        if (!kitsData) return [];
        return Object.values(kitsData).flatMap(cat => cat.items)
            .filter(kit => kit.relatedLaws?.some(rl => {
                const checkName = isRelatedLawObject(rl) ? rl.name : rl;
                return checkName.includes(lawName) || lawName.includes(checkName);
            }));
    };

    if (loading) return <div className="p-8 text-center text-slate-500">법령 가이드를 불러오는 중...</div>;
    if (error) return <div className="p-8 text-center text-red-500">{error}</div>;
    if (!data) return null;

    const chapters = Object.entries(data);
    const currentChapter = data[activeChapter];

    const handleDownload = (path: string, filename: string) => {
        try {
            const baseURL = process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:8000/api/v1";

            // If path already starts with actionkits/files, just use it with baseURL
            // If it starts with library/resources, swap it to the new structure
            let finalPath = path;
            if (path.startsWith('library/resources/')) {
                finalPath = path.replace('library/resources/', 'actionkits/files/');
            }

            // Build absolute URL
            const url = finalPath.startsWith('http') ? finalPath : `${baseURL}/${finalPath}`;

            const link = document.createElement('a');
            link.href = url;
            link.target = "_blank";
            link.download = filename;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        } catch (err) {
            console.error('Download failed:', err);
            alert('다운로드 중 오류가 발생했습니다.');
        }
    };

    const filteredItems: LawItemWithChapter[] = Object.values(data).flatMap(chapter =>
        chapter.items.map(item => ({ ...item, chapterTitle: chapter.title }))
    ).filter(item =>
        item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        item.summary.toLowerCase().includes(searchQuery.toLowerCase())
    );

    const displayItems: Array<LawItem & { chapterTitle?: string }> = searchQuery
        ? filteredItems
        : (currentChapter?.items ?? []);

    return (
        <div className="space-y-8 animate-in fade-in duration-500">
            {/* Header with Search */}
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
                <div>
                    <h2 className="text-2xl font-bold text-slate-900">창업 법령 가이드</h2>
                    <p className="text-sm text-slate-500 mt-1">
                        {searchQuery ? `'${searchQuery}' 검색 결과` : `${currentChapter?.title} 관련 법령을 확인하세요.`}
                    </p>
                </div>
                <div className="relative w-full md:w-64">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                    <input
                        type="text"
                        placeholder="법령, 조항 검색..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-full text-sm focus:ring-2 focus:ring-[#36a4f2]/20 transition-all outline-none"
                    />
                </div>
            </div>

            {/* Chapter Navigation (Only show if not searching) */}
            {!searchQuery && (
                <div className="flex flex-wrap gap-2 overflow-x-auto pb-2">
                    {chapters.map(([id, chapter]) => (
                        <Button
                            key={id}
                            variant={activeChapter === id ? "default" : "outline"}
                            size="sm"
                            onClick={() => setActiveChapter(id)}
                            className={`rounded-full px-4 h-9 ${activeChapter === id ? 'bg-[#36a4f2] hover:bg-[#258bd1]' : 'text-slate-500'}`}
                        >
                            {chapter.title}
                        </Button>
                    ))}
                </div>
            )}

            {/* Law Cards Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {displayItems.map((item, index) => {
                    const isCompleted = completedItems.has(item.name);

                    return (
                        <Card
                            key={`${item.name}-${index}`}
                            className={`group transition-all duration-300 shadow-sm hover:shadow-md cursor-pointer flex flex-col justify-between ${isCompleted ? 'bg-slate-50/50 border-emerald-500/30' : 'hover:border-[#36a4f2]'
                                }`}
                            onClick={() => setSelectedLaw(item)}
                        >
                            <CardContent className="p-6">
                                <div className="flex justify-between items-start mb-4">
                                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center transition-colors ${isCompleted ? 'bg-emerald-100 text-emerald-600' :
                                        item.ext === '.pdf' ? 'bg-red-50 text-red-500' : 'bg-[#36a4f2]/10 text-[#36a4f2]'
                                        }`}>
                                        {isCompleted ? <CheckCircle2 className="w-5 h-5" /> : <FileText className="w-5 h-5" />}
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <button
                                            onClick={(e) => toggleItemCompletion(e, item.name)}
                                            className={`p-1.5 rounded-md transition-all ${isCompleted ? 'text-emerald-500 bg-emerald-50 hover:bg-emerald-100' : 'text-slate-300 hover:bg-slate-100 hover:text-slate-600'
                                                }`}
                                            title={isCompleted ? "읽음 표시 해제" : "읽음 표시"}
                                        >
                                            {isCompleted ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4" />}
                                        </button>
                                        <div className="flex flex-col items-end gap-1">
                                            {item.chapterTitle && (
                                                <Badge variant="secondary" className="text-[9px] px-1.5 py-0 bg-[#36a4f2]/5 text-[#36a4f2] uppercase">
                                                    {item.chapterTitle.split(' ')[0]}
                                                </Badge>
                                            )}
                                            <Badge variant="outline" className={`text-[10px] font-bold uppercase ${isCompleted ? 'text-emerald-400 border-emerald-200' : 'text-slate-400'}`}>
                                                {item.ext.replace('.', '')}
                                            </Badge>
                                        </div>
                                    </div>
                                </div>
                                <h4 className={`font-bold mb-2 transition-colors line-clamp-2 ${isCompleted ? 'text-slate-500' : 'text-slate-800 group-hover:text-[#36a4f2]'
                                    }`}>
                                    {item.name}
                                </h4>
                                <p className={`text-xs line-clamp-2 mb-4 leading-relaxed ${isCompleted ? 'text-slate-400' : 'text-slate-500'
                                    }`}>
                                    {item.summary}
                                </p>

                                {item.highlights && item.highlights.length > 0 && (
                                    <div className="space-y-1.5 mb-4">
                                        {item.highlights.slice(0, 2).map((h, i) => (
                                            <div key={i} className="flex items-start gap-2 text-[11px] text-slate-600">
                                                <CheckCircle2 className="w-3 h-3 text-[#36a4f2] mt-0.5 shrink-0" />
                                                <span className="line-clamp-1">{h}</span>
                                            </div>
                                        ))}
                                    </div>
                                )}

                                {/* Smart Linkage: Related Action Kits */}
                                {(() => {
                                    const relatedKits = getRelatedKits(item.name);
                                    if (relatedKits.length === 0) return null;
                                    return (
                                        <div className="mb-4 p-3 bg-slate-50 rounded-xl border border-slate-100/50">
                                            <div className="flex items-center gap-1.5 mb-2">
                                                <FolderOpen className="w-3 h-3 text-[#36a4f2]" />
                                                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">실무 활용 키트</span>
                                            </div>
                                            <div className="space-y-1.5">
                                                {relatedKits.map((kit, i) => (
                                                    <button
                                                        key={i}
                                                        onClick={(e) => {
                                                            e.stopPropagation();
                                                            onNavigateToKit?.(kit.name);
                                                        }}
                                                        className="w-full flex items-center justify-between gap-2 p-1.5 bg-white border border-slate-100 rounded-lg group/kit hover:border-[#36a4f2]/30 transition-all shadow-sm"
                                                    >
                                                        <span className="text-[10px] font-bold text-slate-700 line-clamp-1 group-hover/kit:text-[#36a4f2] text-left">
                                                            {kit.name}
                                                        </span>
                                                        <Badge variant="outline" className="text-[8px] py-0 px-1 border-slate-200 text-slate-400 group-hover/kit:border-[#36a4f2]/20 group-hover/kit:text-[#36a4f2]/70 shrink-0">
                                                            {kit.type}
                                                        </Badge>
                                                    </button>
                                                ))}
                                            </div>
                                        </div>
                                    );
                                })()}

                                <div className="mt-auto pt-4 border-t border-slate-50 flex justify-between items-center">
                                    <span className="text-[11px] font-medium text-slate-400">{item.size}</span>
                                    <Button
                                        variant="ghost"
                                        size="icon"
                                        className="w-8 h-8 rounded-full text-slate-400 hover:text-white hover:bg-[#36a4f2]"
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            handleDownload(item.path, item.name);
                                        }}
                                    >
                                        <Download className="w-4 h-4" />
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    );
                })}

                {displayItems.length === 0 && (
                    <div className="col-span-full py-20 flex flex-col items-center justify-center text-slate-400">
                        <Info className="w-12 h-12 mb-4 opacity-20" />
                        <p className="text-lg font-bold">검색 결과가 없습니다.</p>
                        <p className="text-sm">다른 키워드로 다시 검색해 보세요.</p>
                    </div>
                )}
            </div>

            {/* Law Detail Popup */}
            {selectedLaw && (
                <LawDetailPopup
                    item={selectedLaw}
                    relatedKits={getRelatedKits(selectedLaw.name)}
                    onClose={() => setSelectedLaw(null)}
                    onNavigateToKit={onNavigateToKit}
                    onDownload={handleDownload}
                />
            )}

            {/* AI Call to Action */}
            <div className="bg-slate-900 rounded-3xl p-8 text-white relative overflow-hidden shadow-xl">
                <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-br from-[#36a4f2]/20 to-purple-500/20 blur-2xl" />
                <div className="relative z-10 flex flex-col md:flex-row items-center justify-between gap-6">
                    <div>
                        <div className="flex items-center gap-2 mb-2">
                            <Sparkles className="w-4 h-4 text-[#36a4f2]" />
                            <span className="text-xs font-bold uppercase tracking-widest text-[#36a4f2]">AI Assistant</span>
                        </div>
                        <h3 className="text-xl font-bold mb-1">법적 의무 사항이 헷갈리시나요?</h3>
                        <p className="text-slate-400 text-sm">AI 법률 전문가에게 질문하고 즉시 해결책을 얻으세요.</p>
                    </div>
                    <Button className="bg-white text-slate-900 hover:bg-slate-100 rounded-full font-bold px-6">
                        AI 상담 시작하기
                    </Button>
                </div>
            </div>

            {/* Disclaimer */}
            <div className="mt-16 bg-slate-50/50 rounded-2xl p-6 md:p-8 border border-slate-100">
                <h5 className="text-xs font-bold text-slate-500 mb-3 tracking-tight">법적 면책 조항 (Disclaimer)</h5>
                <p className="text-[11px] leading-relaxed text-slate-400 break-keep">
                    본 조사자료는 고객의 창업에 정보를 제공할 목적으로 작성되었으며, 어떠한 경우에도 무단 복제 및 배포 될 수 없습니다.<br />
                    또한 본 자료에 수록된 내용은 당사가 신뢰할 만한 자료 및 정보로 얻어진 것이나, 그 정확성이나 완전성을 보장할 수 없으므로
                    창업자 자신의 판단과 책임하에 최종결정을 하시기 바랍니다.<br />
                    <span className="text-slate-500 font-medium mt-1 inline-block">따라서 어떠한 경우에도 본 자료는 고객의 창업의 결과에 대한 법적 책임소재의 증빙자료로 사용될 수 없습니다.</span>
                </p>
            </div>
        </div>
    );
};

'use client';

import React, { useState, useRef } from 'react';
import { Camera, Paperclip, Send, X, FileText } from 'lucide-react';
import { AxiosError } from 'axios';
import { growthClubApi } from '../api';

interface CreatePostFormProps {
    onSuccess: () => void;
}

const MAX_IMAGE_MB = 20;
const MAX_FILE_MB = 50;
const MAX_TOTAL_MB = 200;
const MAX_IMAGE_COUNT = 10;
const MAX_FILE_COUNT = 10;
const MAX_IMAGE_BYTES = MAX_IMAGE_MB * 1024 * 1024;
const MAX_FILE_BYTES = MAX_FILE_MB * 1024 * 1024;
const MAX_TOTAL_BYTES = MAX_TOTAL_MB * 1024 * 1024;
const IMAGE_EXTENSIONS = new Set([".jpg", ".jpeg", ".png", ".webp"]);
const FILE_EXTENSIONS = new Set([".pdf", ".doc", ".docx", ".hwp", ".xls", ".xlsx", ".ppt", ".pptx", ".txt"]);

const getExt = (name: string) => {
    const idx = name.lastIndexOf(".");
    return idx >= 0 ? name.slice(idx).toLowerCase() : "";
};

export const CreatePostForm: React.FC<CreatePostFormProps> = ({ onSuccess }) => {
    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');
    const [category, setCategory] = useState('free');
    const [isSubmitting, setIsSubmitting] = useState(false);

    // 파일 업로드 상태
    const [imageFiles, setImageFiles] = useState<File[]>([]);
    const [imagePreviews, setImagePreviews] = useState<string[]>([]);
    const [otherFiles, setOtherFiles] = useState<File[]>([]);

    const imageInputRef = useRef<HTMLInputElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const incoming = Array.from(e.target.files || []);
        if (incoming.length === 0) return;

        if (imageFiles.length + incoming.length > MAX_IMAGE_COUNT) {
            alert(`이미지는 최대 ${MAX_IMAGE_COUNT}개까지 첨부할 수 있습니다.`);
            if (imageInputRef.current) imageInputRef.current.value = '';
            return;
        }

        const currentTotalBytes = imageFiles.reduce((sum, file) => sum + file.size, 0)
            + otherFiles.reduce((sum, file) => sum + file.size, 0);
        let totalBytes = currentTotalBytes;

        const accepted: File[] = [];
        const rejected: string[] = [];
        incoming.forEach((file) => {
            const ext = getExt(file.name);
            const isImageType = (file.type || "").startsWith("image/");
            if (!isImageType || !IMAGE_EXTENSIONS.has(ext)) {
                rejected.push(`${file.name}: 허용되지 않은 이미지 형식`);
                return;
            }
            if (file.size > MAX_IMAGE_BYTES) {
                rejected.push(`${file.name}: ${MAX_IMAGE_MB}MB 초과`);
                return;
            }
            if (totalBytes + file.size > MAX_TOTAL_BYTES) {
                rejected.push(`${file.name}: 전체 첨부 ${MAX_TOTAL_MB}MB 초과`);
                return;
            }
            totalBytes += file.size;
            accepted.push(file);
        });

        if (rejected.length > 0) {
            alert(rejected.join("\n"));
        }
        if (accepted.length === 0) {
            if (imageInputRef.current) imageInputRef.current.value = '';
            return;
        }

        setImageFiles((prev) => [...prev, ...accepted]);
        accepted.forEach((file) => {
            const reader = new FileReader();
            reader.onloadend = () => {
                setImagePreviews((prev) => [...prev, String(reader.result || "")]);
            };
            reader.readAsDataURL(file);
        });
    };

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const incoming = Array.from(e.target.files || []);
        if (incoming.length === 0) return;

        if (otherFiles.length + incoming.length > MAX_FILE_COUNT) {
            alert(`일반 파일은 최대 ${MAX_FILE_COUNT}개까지 첨부할 수 있습니다.`);
            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        }

        const currentTotalBytes = imageFiles.reduce((sum, file) => sum + file.size, 0)
            + otherFiles.reduce((sum, file) => sum + file.size, 0);
        let totalBytes = currentTotalBytes;

        const accepted: File[] = [];
        const rejected: string[] = [];
        incoming.forEach((file) => {
            const ext = getExt(file.name);
            if (!FILE_EXTENSIONS.has(ext)) {
                rejected.push(`${file.name}: 허용되지 않은 파일 형식`);
                return;
            }
            if (file.size > MAX_FILE_BYTES) {
                rejected.push(`${file.name}: ${MAX_FILE_MB}MB 초과`);
                return;
            }
            if (totalBytes + file.size > MAX_TOTAL_BYTES) {
                rejected.push(`${file.name}: 전체 첨부 ${MAX_TOTAL_MB}MB 초과`);
                return;
            }
            totalBytes += file.size;
            accepted.push(file);
        });

        if (rejected.length > 0) {
            alert(rejected.join("\n"));
        }
        if (accepted.length === 0) {
            if (fileInputRef.current) fileInputRef.current.value = '';
            return;
        }

        setOtherFiles((prev) => [...prev, ...accepted]);
    };

    const removeImage = (index: number) => {
        setImageFiles((prev) => prev.filter((_, i) => i !== index));
        setImagePreviews((prev) => prev.filter((_, i) => i !== index));
        if (imageInputRef.current) imageInputRef.current.value = '';
    };

    const removeFile = (index: number) => {
        setOtherFiles((prev) => prev.filter((_, i) => i !== index));
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!title || !content) return;

        setIsSubmitting(true);
        try {
            const formData = new FormData();
            formData.append('title', title);
            formData.append('content', content);
            formData.append('category', category);

            imageFiles.forEach((it) => formData.append('images', it));
            otherFiles.forEach((it) => formData.append('files', it));

            await growthClubApi.createPost(formData);
            setTitle('');
            setContent('');
            setImageFiles([]);
            setImagePreviews([]);
            setOtherFiles([]);
            if (imageInputRef.current) imageInputRef.current.value = '';
            if (fileInputRef.current) fileInputRef.current.value = '';
            onSuccess();
        } catch (error: unknown) {
            console.error('Failed to create post:', error);
            const status = error instanceof AxiosError ? error.response?.status : undefined;
            if (status === 401) {
                alert('인증이 만료되었습니다. 다시 로그인해주세요.');
            } else {
                alert('게시글 작성에 실패했습니다. 네트워크 상태를 확인해주세요.');
            }
        } finally {
            setIsSubmitting(false);
        }
    };

    return (
        <div className="bg-white dark:bg-zinc-900 rounded-2xl shadow-sm border border-zinc-200 dark:border-zinc-800 p-6">
            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="flex gap-2">
                    {['free', 'neighborhood', 'industry'].map((cat) => (
                        <button
                            key={cat}
                            type="button"
                            onClick={() => setCategory(cat)}
                            className={`px-3 py-1.5 rounded-full text-xs font-semibold transition-all ${category === cat
                                ? 'bg-blue-600 text-white'
                                : 'bg-zinc-100 dark:bg-zinc-800 text-zinc-500 hover:bg-zinc-200 dark:hover:bg-zinc-700'
                                }`}
                        >
                            {cat === 'free' ? '자유게시판' : cat === 'neighborhood' ? '동네 소식' : '업종 이야기'}
                        </button>
                    ))}
                </div>

                <input
                    type="text"
                    placeholder="제목을 입력하세요"
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    className="w-full bg-transparent text-lg font-bold placeholder:text-zinc-400 focus:outline-none dark:text-white"
                />

                <textarea
                    placeholder="오늘 어떤 일이 있었나요? 다른 창업자들과 나눠보세요."
                    value={content}
                    onChange={(e) => setContent(e.target.value)}
                    rows={4}
                    className="w-full bg-transparent text-sm placeholder:text-zinc-400 focus:outline-none resize-none dark:text-zinc-300"
                />

                {/* 이미지 미리보기 및 파일 목록 */}
                {(imagePreviews.length > 0 || otherFiles.length > 0) && (
                    <div className="flex flex-wrap gap-3 py-2">
                        {imagePreviews.map((preview, index) => (
                            <div key={`img-${index}`} className="relative group w-24 h-24">
                                <img src={preview} alt="Preview" className="w-full h-full object-cover rounded-lg border border-zinc-100 dark:border-zinc-800" />
                                <button
                                    type="button"
                                    onClick={() => removeImage(index)}
                                    className="absolute -top-2 -right-2 bg-zinc-900/80 text-white p-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                                >
                                    <X size={12} />
                                </button>
                            </div>
                        ))}
                        {otherFiles.map((otherFile, index) => (
                            <div key={`file-${index}-${otherFile.name}`} className="flex items-center gap-2 bg-zinc-50 dark:bg-zinc-800 px-3 py-2 rounded-lg border border-zinc-100 dark:border-zinc-700 group">
                                <FileText size={16} className="text-zinc-400" />
                                <span className="text-xs text-zinc-600 dark:text-zinc-400 max-w-[150px] truncate">
                                    {otherFile.name}
                                </span>
                                <button
                                    type="button"
                                    onClick={() => removeFile(index)}
                                    className="text-zinc-400 hover:text-red-500 transition-colors"
                                >
                                    <X size={14} />
                                </button>
                            </div>
                        ))}
                    </div>
                )}

                <div className="flex items-center justify-between pt-4 border-t border-zinc-100 dark:border-zinc-800">
                    <div className="flex items-center gap-4">
                        <input
                            type="file"
                            accept=".jpg,.jpeg,.png,.webp,image/*"
                            multiple
                            className="hidden"
                            ref={imageInputRef}
                            onChange={handleImageChange}
                        />
                        <button
                            type="button"
                            onClick={() => imageInputRef.current?.click()}
                            className={`text-zinc-400 hover:text-blue-500 transition-colors ${imageFiles.length > 0 ? 'text-blue-500' : ''}`}
                            title="이미지 추가"
                        >
                            <Camera size={20} />
                        </button>

                        <input
                            type="file"
                            accept=".pdf,.doc,.docx,.hwp,.xls,.xlsx,.ppt,.pptx,.txt"
                            multiple
                            className="hidden"
                            ref={fileInputRef}
                            onChange={handleFileChange}
                        />
                        <button
                            type="button"
                            onClick={() => fileInputRef.current?.click()}
                            className={`text-zinc-400 hover:text-blue-500 transition-colors ${otherFiles.length > 0 ? 'text-blue-500' : ''}`}
                            title="파일 추가"
                        >
                            <Paperclip size={20} />
                        </button>
                    </div>
                    <button
                        type="submit"
                        disabled={isSubmitting || !title || !content}
                        className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed text-white text-sm font-bold rounded-xl transition-all shadow-lg shadow-blue-500/20"
                    >
                        <Send size={16} />
                        <span>{isSubmitting ? '게시 중...' : '등록하기'}</span>
                    </button>
                </div>
            </form>
        </div>
    );
};

'use client';

import React, { useState } from 'react';
import { Post } from '../types';
import { MessageSquare, ThumbsUp, Trash2, AlertCircle, Paperclip } from 'lucide-react';

import { useAuth } from '@/providers/AuthProvider';
import { growthClubApi } from '../api';
import { CommentSection } from './CommentSection';
import { resolveUploadUrl } from '../utils/upload-url';

interface PostCardProps {
    post: Post;
    onDeleteSuccess?: () => void;
    onReportSuccess?: () => void;
}

const formatTimeAgo = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffInSeconds = Math.floor((now.getTime() - date.getTime()) / 1000);

    if (diffInSeconds < 60) return '방금 전';
    if (diffInSeconds < 3600) return `${Math.floor(diffInSeconds / 60)}분 전`;
    if (diffInSeconds < 86400) return `${Math.floor(diffInSeconds / 3600)}시간 전`;
    if (diffInSeconds < 2592000) return `${Math.floor(diffInSeconds / 86400)}일 전`;
    return date.toLocaleDateString('ko-KR');
};

export const PostCard: React.FC<PostCardProps> = ({ post, onDeleteSuccess, onReportSuccess }) => {
    const { user } = useAuth();
    const [isDeleting, setIsDeleting] = useState(false);
    const [showComments, setShowComments] = useState(false);

    // 좋아요 상태 관리를 위한 로컬 스테이트
    const [liked, setLiked] = useState(post.is_liked);
    const [likesCount, setLikesCount] = useState(post.likes_count);
    const [isLiking, setIsLiking] = useState(false);
    const attachments = post.attachments ?? [];
    const imageAttachments = attachments.filter((it) => it.kind === "image");
    const fileAttachments = attachments.filter((it) => it.kind === "file");

    const isAuthor = user && String(user.id) === String(post.author_id);

    const handleDelete = async () => {
        if (!window.confirm('정말 이 게시글을 삭제하시겠습니까?')) return;

        setIsDeleting(true);
        try {
            await growthClubApi.deletePost(post.id);
            if (onDeleteSuccess) {
                onDeleteSuccess();
            }
        } catch (error) {
            console.error('Failed to delete post:', error);
            alert('게시글 삭제에 실패했습니다.');
        } finally {
            setIsDeleting(false);
        }
    };

    const handleReport = async () => {
        if (!window.confirm('이 게시물을 신고하시겠습니까?')) return;

        try {
            const result = await growthClubApi.reportPost(post.id);
            alert(result.message);
            if (result.is_blinded && onDeleteSuccess) {
                onDeleteSuccess(); // 블라인드 처리되면 목록에서 제거하기 위해 같은 콜백 사용
            } else if (onReportSuccess) {
                onReportSuccess();
            }
        } catch (error) {
            console.error('Failed to report post:', error);
            alert('게시글 신고에 실패했습니다.');
        }
    };

    const handleLike = async () => {
        if (!user) {
            alert('좋아요를 누르려면 먼저 로그인해주세요.');
            return;
        }
        if (isLiking) return;

        // 낙관적 업데이트
        const prevLiked = liked;
        const prevCount = likesCount;
        setLiked(!prevLiked);
        setLikesCount(prevLiked ? prevCount - 1 : prevCount + 1);
        setIsLiking(true);

        try {
            const result = await growthClubApi.likePost(post.id);
            // 실제 데이터로 동기화
            setLiked(result.liked);
            setLikesCount(result.likes_count);
        } catch (error) {
            console.error('Failed to like post:', error);
            // 에러 시 롤백
            setLiked(prevLiked);
            setLikesCount(prevCount);
        } finally {
            setIsLiking(false);
        }
    };

    return (
        <article className={`bg-white dark:bg-zinc-900 rounded-xl shadow-sm border border-zinc-200 dark:border-zinc-800 p-6 transition-all hover:shadow-md ${isDeleting ? 'opacity-50 pointer-events-none' : ''}`}>
            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-blue-100 flex items-center justify-center text-blue-600 font-bold">
                        {post.author.username[0]}
                    </div>
                    <div>
                        <h3 className="text-sm font-semibold text-zinc-900 dark:text-white">{post.author.username}</h3>
                        <p className="text-xs text-zinc-500">
                            {formatTimeAgo(post.created_at)} · {post.neighborhood}
                        </p>
                    </div>
                </div>

                {isAuthor && (
                    <button
                        onClick={handleDelete}
                        className="p-2 text-zinc-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                        title="게시글 삭제"
                    >
                        <Trash2 size={18} />
                    </button>
                )}
            </div>

            <div className="flex gap-2 mb-4">
                <span className="px-2 py-1 bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400 text-[10px] font-bold rounded">
                    {post.neighborhood}
                </span>
                <span className="px-2 py-1 bg-orange-50 dark:bg-orange-900/30 text-orange-600 dark:text-orange-400 text-[10px] font-bold rounded">
                    {post.industry}
                </span>
            </div>

            <h2 className="text-xl font-bold text-zinc-900 dark:text-white mb-2">{post.title}</h2>
            <p className="text-zinc-600 dark:text-zinc-400 text-sm leading-relaxed mb-4 whitespace-pre-wrap">
                {post.content}
            </p>

            {imageAttachments.length > 0 && (
                <div className="mb-4 grid grid-cols-1 gap-2 sm:grid-cols-2">
                    {imageAttachments.map((attachment) => (
                        <div key={attachment.id} className="rounded-lg overflow-hidden border border-zinc-100 dark:border-zinc-800">
                            <img
                                src={resolveUploadUrl(attachment.object_key)}
                                alt={attachment.original_filename || "Post content"}
                                className="w-full object-cover max-h-96"
                            />
                        </div>
                    ))}
                </div>
            )}

            {fileAttachments.length > 0 && (
                <div className="mb-4 flex flex-col gap-2">
                    {fileAttachments.map((attachment) => (
                        <a
                            key={attachment.id}
                            href={resolveUploadUrl(attachment.object_key)}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-2 px-3 py-2 bg-zinc-50 dark:bg-zinc-800 border border-zinc-200 dark:border-zinc-700 rounded-lg text-xs text-zinc-600 dark:text-zinc-400 hover:bg-zinc-100 dark:hover:bg-zinc-700 transition-colors"
                        >
                            <Paperclip size={14} />
                            <span>{attachment.original_filename || "첨부 파일 다운로드"}</span>
                        </a>
                    ))}
                </div>
            )}


            <div className="flex items-center gap-6 pt-4 border-t border-zinc-100 dark:border-zinc-800">
                <button
                    onClick={handleLike}
                    disabled={isLiking}
                    className={`flex items-center gap-2 text-sm transition-colors ${liked ? 'text-blue-600' : 'text-zinc-500 hover:text-blue-600'}`}
                >
                    <ThumbsUp size={18} fill={liked ? "currentColor" : "none"} />
                    <span>좋아요 {likesCount > 0 ? likesCount : ''}</span>
                </button>
                <button
                    onClick={() => setShowComments(!showComments)}
                    className={`flex items-center gap-2 text-sm transition-colors ${showComments ? 'text-blue-600 font-bold' : 'text-zinc-500 hover:text-blue-600'}`}
                >
                    <MessageSquare size={18} />
                    <span>댓글 {post.comments.length}</span>
                </button>
                {!isAuthor && (
                    <button
                        onClick={handleReport}
                        className="flex items-center gap-2 text-zinc-500 hover:text-red-500 text-sm ml-auto"
                        title="게시글 신고"
                    >
                        <AlertCircle size={18} />
                        <span>신고</span>
                    </button>
                )}
            </div>

            {showComments && (
                <CommentSection
                    postId={post.id}
                    initialComments={post.comments}
                    onCommentAdded={onDeleteSuccess || (() => { })}
                />
            )}
        </article>
    );
};

import { useEffect, useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Loader2, UploadCloud, File as FileIcon, CheckCircle2, Download, Clock, Scale, Highlighter, CheckSquare, Plus, X } from "lucide-react";
import { apiClient } from "@/lib/api-client";
import { useDropzone } from "react-dropzone";
import { fetchItemDetail } from "../api";

interface ActionKitFileRecord {
    id: number;
    version: number;
    is_current: boolean;
    original_filename?: string;
    size_bytes?: number;
}

interface ActionKitEditItem {
    id?: number;
    isNew?: boolean;
    category_id?: number;
    name?: string;
    summary?: string;
    is_active?: boolean;
    sort_order?: number;
    files?: ActionKitFileRecord[];
}

interface ActionKitEditModalProps {
    item: ActionKitEditItem;
    isOpen: boolean;
    onClose: () => void;
    onSaved: () => void;
}

export function ActionKitEditModal({ item, isOpen, onClose, onSaved }: ActionKitEditModalProps) {
    const [loading, setLoading] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [uploadSuccess, setUploadSuccess] = useState(false);
    const [currentItem, setCurrentItem] = useState<any>(item);

    const [formData, setFormData] = useState({
        domain: "kits",
        category_id: item?.category_id || 1,
        name: "",
        summary: "",
        is_active: false,
        sort_order: 0,
    });

    useEffect(() => {
        if (item && isOpen) {
            setCurrentItem(item);
            setFormData({
                domain: "kits",
                category_id: item.category_id || 1,
                name: item.name || "",
                summary: item.summary || "",
                is_active: item.is_active ?? false,
                sort_order: item.sort_order || 0,
            });
        }
    }, [item, isOpen]);

    const refreshItem = async () => {
        if (!currentItem?.id) return;
        try {
            const updated = await fetchItemDetail(currentItem.id);
            setCurrentItem(updated);
        } catch (e) {
            console.error('Failed to refresh item:', e);
        }
    };

    const isNew = currentItem?.isNew === true;

    const onDrop = async (acceptedFiles: File[]) => {
        if (!currentItem?.id || acceptedFiles.length === 0) return;

        const file = acceptedFiles[0];
        const formData = new FormData();
        formData.append("file", file);

        setUploading(true);
        setUploadSuccess(false);
        try {
            await apiClient.post(`/ops/actionkit/items/${currentItem.id}/files`, formData, {
                headers: {
                    'Content-Type': 'multipart/form-data'
                }
            });
            setUploadSuccess(true);
            onSaved();
            await refreshItem();
            setTimeout(() => setUploadSuccess(false), 3000);
        } catch (error) {
            console.error("Failed to upload file:", error);
            alert("파일 업로드 중 오류가 발생했습니다.");
        } finally {
            setUploading(false);
        }
    };

    const { getRootProps, getInputProps, isDragActive } = useDropzone({
        onDrop,
        multiple: false
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            if (isNew) {
                await apiClient.post(`/ops/actionkit/items`, formData);
            } else {
                if (!currentItem?.id) return;
                await apiClient.patch(`/ops/actionkit/items/${currentItem.id}`, formData);
            }
            onSaved();
            onClose();
        } catch (error) {
            console.error("Failed to update item:", error);
            alert("저장 중 오류가 발생했습니다.");
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={isOpen} onOpenChange={(open: boolean) => !open && onClose()}>
            <DialogContent className="sm:max-w-[500px] max-h-[85vh] border-slate-100 p-0 bg-white shadow-xl rounded-2xl flex flex-col">
                <DialogHeader className="p-6 pb-2 border-b border-slate-100 flex flex-row items-center justify-between flex-shrink-0">
                    <div>
                        <DialogTitle className="text-xl font-bold text-slate-800">
                            {isNew ? "새 문서 등록" : "문서 정보 수정"}
                        </DialogTitle>
                        <p className="text-sm text-slate-500 mt-1">
                            {isNew ? "새로운 문서 항목을 카테고리에 추가합니다." : "변경사항은 저장 즉시 앱 화면에 실시간으로 반영됩니다."}
                        </p>
                    </div>
                </DialogHeader>

                <form onSubmit={handleSubmit} className="p-6 space-y-5 bg-slate-50/50 overflow-y-auto flex-1">
                    <div className="space-y-2">
                        <Label htmlFor="name" className="text-slate-700 font-semibold text-sm">항목 제목</Label>
                        <Input
                            id="name"
                            name="name"
                            value={formData.name}
                            onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                            className="bg-white border-slate-200 focus-visible:ring-[#36a4f2]/30 h-11"
                        />
                    </div>

                    <div className="space-y-2">
                        <Label htmlFor="summary" className="text-slate-700 font-semibold text-sm">요약 설명</Label>
                        <Textarea
                            id="summary"
                            name="summary"
                            value={formData.summary}
                            onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setFormData(prev => ({ ...prev, summary: e.target.value }))}
                            className="bg-white border-slate-200 focus-visible:ring-[#36a4f2]/30 min-h-[100px] resize-none"
                        />
                    </div>

                    <div className="grid grid-cols-2 gap-4 pt-1">
                        <div className="space-y-2">
                            <Label htmlFor="sort_order" className="text-slate-700 font-semibold text-sm">노출 순서 (낮을수록 먼저)</Label>
                            <Input
                                id="sort_order"
                                name="sort_order"
                                type="number"
                                value={formData.sort_order}
                                onChange={(e: React.ChangeEvent<HTMLInputElement>) => setFormData(prev => ({ ...prev, sort_order: parseInt(e.target.value) || 0 }))}
                                className="bg-white border-slate-200 focus-visible:ring-[#36a4f2]/30 h-11"
                            />
                        </div>

                        <div className="space-y-3 flex flex-col justify-end pb-2">
                            <div className="flex items-center justify-between bg-white border border-slate-200 p-3 rounded-lg h-11">
                                <Label htmlFor="is_active" className="text-slate-600 font-semibold text-sm cursor-pointer mb-0">
                                    사용자에게 공개
                                </Label>
                                <Switch
                                    id="is_active"
                                    checked={formData.is_active}
                                    onCheckedChange={(checked: boolean) => setFormData(prev => ({ ...prev, is_active: checked }))}
                                />
                            </div>
                        </div>
                    </div>

                    {/* File Upload Area (Only show for existing items, not when creating new) */}
                    {!isNew && currentItem?.id && (
                        <div className="pt-2">
                            <Label className="text-slate-700 font-semibold text-sm mb-2 block">파일 관리</Label>
                            <div
                                {...getRootProps()}
                                className={`border-2 border-dashed rounded-xl p-6 text-center transition-colors cursor-pointer
                                    ${isDragActive ? 'border-[#36a4f2] bg-[#36a4f2]/5' : 'border-slate-200 bg-white hover:bg-slate-50'}`}
                            >
                                <input {...getInputProps()} />
                                {uploading ? (
                                    <div className="flex flex-col items-center justify-center space-y-2 text-[#36a4f2]">
                                        <Loader2 className="w-8 h-8 animate-spin" />
                                        <p className="text-sm font-semibold">새 버전을 업로드하는 중입니다...</p>
                                    </div>
                                ) : uploadSuccess ? (
                                    <div className="flex flex-col items-center justify-center space-y-2 text-emerald-500">
                                        <CheckCircle2 className="w-8 h-8" />
                                        <p className="text-sm font-semibold">최신 파일로 성공적으로 업데이트되었습니다!</p>
                                    </div>
                                ) : (
                                    <div className="flex flex-col items-center justify-center space-y-2 text-slate-500">
                                        <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center mb-1">
                                            <UploadCloud className="w-5 h-5 text-slate-400" />
                                        </div>
                                        <p className="text-sm font-semibold text-slate-700">
                                            마우스로 파일을 끌어다 놓거나 <span className="text-[#36a4f2]">클릭해서 선택</span>하세요.
                                        </p>
                                        <p className="text-xs text-slate-400">
                                            현재 첨부된 파일 버전: v{currentItem.files?.length ? Math.max(...currentItem.files.map((f: ActionKitFileRecord) => f.version)) : "없음"}
                                        </p>
                                    </div>
                                )}
                            </div>

                            {/* Version History */}
                            {currentItem.files?.length > 0 && (
                                <div className="mt-3">
                                    <div className="flex items-center gap-1.5 mb-2">
                                        <Clock className="w-3.5 h-3.5 text-slate-400" />
                                        <span className="text-xs font-semibold text-slate-500">버전 히스토리 ({currentItem.files.length}개)</span>
                                    </div>
                                    <div className="space-y-1.5 max-h-[160px] overflow-y-auto">
                                        {[...currentItem.files].sort((a: ActionKitFileRecord, b: ActionKitFileRecord) => b.version - a.version).map((f: ActionKitFileRecord) => (
                                            <div key={f.id} className={`flex items-center justify-between p-2.5 rounded-lg border text-xs transition-colors ${f.is_current
                                                ? 'bg-[#36a4f2]/5 border-[#36a4f2]/20'
                                                : 'bg-white border-slate-100 hover:bg-slate-50'
                                                }`}>
                                                <div className="flex items-center gap-2 min-w-0 flex-1">
                                                    <FileIcon className={`w-4 h-4 flex-shrink-0 ${f.is_current ? 'text-[#36a4f2]' : 'text-slate-400'}`} />
                                                    <div className="min-w-0">
                                                        <p className="font-semibold text-slate-700 truncate">
                                                            v{f.version} {f.is_current && <span className="text-[#36a4f2]">(최신)</span>}
                                                        </p>
                                                        <p className="text-slate-400 truncate">
                                                            {f.original_filename || '파일명 없음'} · {f.size_bytes ? `${(f.size_bytes / 1024).toFixed(0)}KB` : ''}
                                                        </p>
                                                    </div>
                                                </div>
                                                <button
                                                    type="button"
                                                    onClick={async () => {
                                                        try {
                                                            const res = await apiClient.get(`/ops/actionkit/files/${f.id}/download`, { responseType: 'blob' });
                                                            const url = window.URL.createObjectURL(new Blob([res.data]));
                                                            const link = document.createElement('a');
                                                            link.href = url;
                                                            link.setAttribute('download', f.original_filename || 'download');
                                                            document.body.appendChild(link);
                                                            link.click();
                                                            link.remove();
                                                            window.URL.revokeObjectURL(url);
                                                        } catch {
                                                            alert("파일 다운로드 중 오류가 발생했습니다.");
                                                        }
                                                    }}
                                                    className="flex items-center gap-1 px-2.5 py-1.5 rounded-md bg-white border border-slate-200 text-slate-500 hover:text-[#36a4f2] hover:border-[#36a4f2]/30 transition-colors flex-shrink-0 ml-2"
                                                >
                                                    <Download className="w-3.5 h-3.5" />
                                                    <span className="font-semibold">받기</span>
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    )}

                    {/* Related Laws Section */}
                    {!isNew && currentItem?.id && (
                        <div className="pt-2">
                            <Label className="text-slate-700 font-semibold text-sm mb-2 flex items-center gap-1.5">
                                <Scale className="w-3.5 h-3.5" /> 관련 법령
                            </Label>
                            <div className="space-y-1.5 mt-2">
                                {currentItem.related_laws?.map((law: any) => (
                                    <div key={law.id} className="flex items-center justify-between p-2.5 rounded-lg border border-slate-100 bg-white text-xs">
                                        <div className="min-w-0 flex-1">
                                            <p className="font-semibold text-slate-700 truncate">{law.law_name}</p>
                                            {law.law_summary && <p className="text-slate-400 truncate mt-0.5">{law.law_summary}</p>}
                                        </div>
                                        <button type="button" onClick={async () => {
                                            await apiClient.delete(`/ops/actionkit/related-laws/${law.id}`);
                                            onSaved?.();
                                            await refreshItem();
                                        }} className="text-slate-300 hover:text-red-400 transition-colors ml-2 flex-shrink-0">
                                            <X className="w-4 h-4" />
                                        </button>
                                    </div>
                                ))}
                            </div>
                            <div className="flex gap-2 mt-2">
                                <Input id="add_law_name" placeholder="법령명 (예: 건축법 제11조)" className="bg-white border-slate-200 h-9 text-xs flex-1" />
                                <Input id="add_law_summary" placeholder="요약 (선택)" className="bg-white border-slate-200 h-9 text-xs flex-1" />
                                <Button type="button" size="sm" className="bg-[#36a4f2] hover:bg-[#258bd1] h-9 px-3 flex-shrink-0" onClick={async () => {
                                    const nameEl = document.getElementById('add_law_name') as HTMLInputElement;
                                    const summaryEl = document.getElementById('add_law_summary') as HTMLInputElement;
                                    if (!nameEl.value.trim()) return;
                                    await apiClient.post(`/ops/actionkit/items/${currentItem.id}/related-laws`, {
                                        law_name: nameEl.value.trim(),
                                        law_summary: summaryEl.value.trim() || null
                                    });
                                    nameEl.value = '';
                                    summaryEl.value = '';
                                    onSaved?.();
                                    await refreshItem();
                                }}>
                                    <Plus className="w-3.5 h-3.5" />
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* Highlights Section */}
                    {!isNew && currentItem?.id && (
                        <div className="pt-2">
                            <Label className="text-slate-700 font-semibold text-sm mb-2 flex items-center gap-1.5">
                                <Highlighter className="w-3.5 h-3.5" /> 핵심 포인트 (하이라이트)
                            </Label>
                            <div className="space-y-1.5 mt-2">
                                {currentItem.highlights?.map((hl: any) => (
                                    <div key={hl.id} className="flex items-center justify-between p-2.5 rounded-lg border border-amber-100 bg-amber-50/50 text-xs">
                                        <p className="font-medium text-slate-700 flex-1 min-w-0 truncate">{hl.content}</p>
                                        <button type="button" onClick={async () => {
                                            await apiClient.delete(`/ops/actionkit/highlights/${hl.id}`);
                                            onSaved?.();
                                            await refreshItem();
                                        }} className="text-slate-300 hover:text-red-400 transition-colors ml-2 flex-shrink-0">
                                            <X className="w-4 h-4" />
                                        </button>
                                    </div>
                                ))}
                            </div>
                            <div className="flex gap-2 mt-2">
                                <Input id="add_hl_content" placeholder="핵심 내용을 입력하세요 (예: 건축 허가 필수 조건)" className="bg-white border-slate-200 h-9 text-xs flex-1" />
                                <Button type="button" size="sm" className="bg-amber-500 hover:bg-amber-600 h-9 px-3 flex-shrink-0" onClick={async () => {
                                    const el = document.getElementById('add_hl_content') as HTMLInputElement;
                                    if (!el.value.trim()) return;
                                    await apiClient.post(`/ops/actionkit/items/${currentItem.id}/highlights`, {
                                        content: el.value.trim()
                                    });
                                    el.value = '';
                                    onSaved?.();
                                    await refreshItem();
                                }}>
                                    <Plus className="w-3.5 h-3.5" />
                                </Button>
                            </div>
                        </div>
                    )}

                    {/* ── Checklist ── */}
                    {currentItem.id && (
                        <div className="mt-6 space-y-3">
                            <div className="flex items-center gap-2">
                                <CheckSquare className="w-4 h-4 text-teal-500" />
                                <h3 className="text-sm font-bold text-slate-700">체크리스트</h3>
                            </div>
                            <div className="space-y-1.5">
                                {(currentItem.checklists || []).map((cl: any) => (
                                    <div key={cl.id} className="flex items-center justify-between bg-teal-50 rounded-lg px-3 py-2 text-sm text-teal-700">
                                        <div className="flex items-center gap-2 min-w-0">
                                            <CheckSquare className="w-3.5 h-3.5 flex-shrink-0" />
                                            <span className="truncate">{cl.content}</span>
                                        </div>
                                        <button type="button" onClick={async () => {
                                            await apiClient.delete(`/ops/actionkit/checklists/${cl.id}`);
                                            onSaved?.();
                                            await refreshItem();
                                        }} className="text-slate-300 hover:text-red-400 transition-colors ml-2 flex-shrink-0">
                                            <X className="w-4 h-4" />
                                        </button>
                                    </div>
                                ))}
                            </div>
                            <div className="flex gap-2 mt-2">
                                <Input id="add_cl_content" placeholder="체크 항목을 입력하세요 (예: 소방안전점검 완료 여부)" className="bg-white border-slate-200 h-9 text-xs flex-1" />
                                <Button type="button" size="sm" className="bg-teal-500 hover:bg-teal-600 h-9 px-3 flex-shrink-0" onClick={async () => {
                                    const el = document.getElementById('add_cl_content') as HTMLInputElement;
                                    if (!el.value.trim()) return;
                                    await apiClient.post(`/ops/actionkit/items/${currentItem.id}/checklists`, {
                                        content: el.value.trim()
                                    });
                                    el.value = '';
                                    onSaved?.();
                                    await refreshItem();
                                }}>
                                    <Plus className="w-3.5 h-3.5" />
                                </Button>
                            </div>
                        </div>
                    )}

                    <div className="flex justify-end gap-2 pt-4 border-t border-slate-200 mt-6">
                        <Button type="button" variant="outline" onClick={onClose} className="border-slate-200 text-slate-600 hover:bg-slate-100">
                            취소
                        </Button>
                        <Button type="submit" disabled={loading} className="bg-[#36a4f2] hover:bg-[#258bd1] text-white shadow-md shadow-[#36a4f2]/20 font-bold px-6">
                            {loading ? <Loader2 className="w-4 h-4 mr-2 animate-spin" /> : null}
                            {loading ? "저장 중..." : "변경사항 저장"}
                        </Button>
                    </div>
                </form>
            </DialogContent>
        </Dialog>
    );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { DragDropContext, Droppable, Draggable, DropResult } from "@hello-pangea/dnd";

import { fetchCategories, fetchCategoryItems, fetchSummary, updateItemOrders } from "./api";
import type { ActionKitItem } from "@/features/actionkit/types";

interface OpsActionKitItem extends ActionKitItem {
  id: number;
  category_id: number;
  is_active: boolean;
  sort_order: number;
  ext?: string;
  file_type?: string;
  updated_at?: string;
  files?: { id: number; version: number; is_current: boolean, created_at?: string }[];
}

import { OpsAccessPlaceholder } from "@/features/ops/shared/ops-access-placeholder";
import { useOpsAccessGuard } from "@/features/ops/shared/use-ops-access-guard";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Search, FolderOpen, Loader2, Edit3, Trash2, Package, Paperclip, EyeOff, Scale, Highlighter, Settings, Plus, GripVertical, BarChart3, AlertTriangle } from "lucide-react";
import { ActionKitEditModal } from "@/features/ops/actionkit/components/actionkit-edit-modal";
import { CategoryEditModal } from "@/features/ops/actionkit/components/category-edit-modal";
import { OpsActionKitStatsDashboard } from "@/features/ops/actionkit/components/stats-dashboard";
import { apiClient } from "@/lib/api-client";

export function OpsActionKitView() {
  const { canRender } = useOpsAccessGuard();

  const [loading, setLoading] = useState(true);
  const [categories, setCategories] = useState<{ id: number; title: string; domain: string }[]>([]);
  const [items, setItems] = useState<OpsActionKitItem[]>([]);
  const [activeCategory, setActiveCategory] = useState<number | null>(null);
  const [editingItem, setEditingItem] = useState<OpsActionKitItem | null>(null);
  const [isCreating, setIsCreating] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [summary, setSummary] = useState<any>(null);
  const [activeDomain, setActiveDomain] = useState<"kits" | "laws" | "stats">("kits");

  const [isCategoryModalOpen, setIsCategoryModalOpen] = useState(false);
  const [editingCategory, setEditingCategory] = useState<any>(null);

  const filteredCategories = categories.filter(cat => cat.domain === activeDomain);

  const filteredItems = items.filter(item => {
    const q = searchQuery.toLowerCase();
    return (
      item.name?.toLowerCase().includes(q) ||
      item.summary?.toLowerCase().includes(q)
    );
  });

  const loadItems = useCallback((categoryId: number) => {
    setLoading(true);
    fetchCategoryItems(categoryId)
      .then((data) => setItems(data))
      .catch(console.error)
      .finally(() => setLoading(false));
  }, []);

  const handleDragEnd = async (result: DropResult) => {
    if (!result.destination) return;
    if (result.source.index === result.destination.index) return;
    if (searchQuery) return; // Disable drag during search

    const reorderedItems = Array.from(filteredItems);
    const [movedItem] = reorderedItems.splice(result.source.index, 1);
    reorderedItems.splice(result.destination.index, 0, movedItem);

    // Update sort_order locally
    const updatedItems = reorderedItems.map((item, index) => ({
      ...item,
      sort_order: index + 1
    }));

    setItems(updatedItems);

    try {
      const payload = updatedItems.map(item => ({ id: item.id, sort_order: item.sort_order }));
      await updateItemOrders(payload);
    } catch (e) {
      console.error("Failed to reorder items", e);
      if (activeCategory) loadItems(activeCategory); // Revert on failure
    }
  };

  const handleDelete = async (item: OpsActionKitItem) => {
    if (!confirm(`"${item.name}" 항목을 정말 삭제하시겠습니까?\n이 작업은 되돌릴 수 없습니다.`)) return;
    try {
      await apiClient.delete(`/ops/actionkit/items/${item.id}`);
      if (activeCategory) loadItems(activeCategory);
      fetchSummary().then(setSummary).catch(console.error);
    } catch (error) {
      console.error("Failed to delete item:", error);
      alert("삭제 중 오류가 발생했습니다.");
    }
  };

  useEffect(() => {
    if (!canRender) return;

    fetchCategories()
      .then((data) => {
        setCategories(data);
        const kitsCategories = data.filter((c: any) => c.domain === "kits");
        if (kitsCategories.length > 0) {
          setActiveCategory(kitsCategories[0].id);
        } else if (data.length > 0) {
          setActiveCategory(data[0].id);
        }
      })
      .catch(console.error);
    fetchSummary().then(setSummary).catch(console.error);
  }, [canRender]);

  useEffect(() => {
    if (activeCategory === null) return;
    let cancelled = false;
    const load = async () => {
      setLoading(true);
      try {
        const data = await fetchCategoryItems(activeCategory);
        if (!cancelled) setItems(data);
      } catch (err) {
        if (!cancelled) console.error(err);
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void load();
    return () => { cancelled = true; };
  }, [activeCategory]);

  const handleDomainChange = (domain: "kits" | "laws" | "stats") => {
    setActiveDomain(domain);
    if (domain !== "stats") {
      const domainCats = categories.filter(c => c.domain === domain);
      if (domainCats.length > 0) {
        setActiveCategory(domainCats[0].id);
      }
    }
  };

  const handleCategorySaved = () => {
    fetchCategories()
      .then((data) => {
        setCategories(data);
        const domainCats = data.filter((c: any) => c.domain === activeDomain);
        if (domainCats.length > 0 && !domainCats.find((c: any) => c.id === activeCategory)) {
          setActiveCategory(domainCats[0].id);
        } else if (data.length > 0 && !activeCategory) {
          setActiveCategory(data[0].id);
        }
      })
      .catch(console.error);
  };

  if (!canRender) return <OpsAccessPlaceholder />;

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-end">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">액션 키트 관리 (Admin)</h1>
          <p className="mt-1 text-sm text-slate-500">
            앱 화면에 노출되는 액션 키트 라이브러리와 법령 가이드를 운영할 수 있습니다.
          </p>
        </div>
        <Button
          className="bg-[#36a4f2] hover:bg-[#258bd1]"
          onClick={() => setIsCreating(true)}
          disabled={!activeCategory}
        >
          + 새 항목 등록
        </Button>
      </header>

      {/* Statistics Cards */}
      {summary && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
          {[
            { icon: Package, label: "전체 항목", value: summary.total_items, color: "text-[#36a4f2]", bg: "bg-[#36a4f2]/10" },
            { icon: Paperclip, label: "파일 첨부", value: summary.items_with_files, color: "text-emerald-500", bg: "bg-emerald-50" },
            { icon: EyeOff, label: "미공개", value: summary.inactive_items, color: "text-orange-500", bg: "bg-orange-50" },
            { icon: Scale, label: "관련 법령", value: summary.total_related_laws, color: "text-violet-500", bg: "bg-violet-50" },
            { icon: Highlighter, label: "하이라이트", value: summary.total_highlights, color: "text-amber-500", bg: "bg-amber-50" },
          ].map((stat) => (
            <Card key={stat.label} className="border-none shadow-sm hover:shadow-md transition-shadow">
              <CardContent className="p-4 flex items-center gap-3">
                <div className={`w-10 h-10 rounded-xl ${stat.bg} flex items-center justify-center flex-shrink-0`}>
                  <stat.icon className={`w-5 h-5 ${stat.color}`} />
                </div>
                <div>
                  <p className="text-2xl font-black text-slate-800 leading-none">{stat.value}</p>
                  <p className="text-[10px] font-bold text-slate-400 mt-1">{stat.label}</p>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Domain Tabs (Top Level) */}
      <div className="flex p-1 bg-slate-100 rounded-2xl w-full md:w-fit shadow-inner overflow-x-auto">
        <button
          onClick={() => handleDomainChange("kits")}
          className={`flex items-center justify-center gap-1.5 md:gap-2 flex-1 md:flex-none py-2.5 px-4 md:px-6 rounded-xl text-sm font-bold whitespace-nowrap transition-all ${activeDomain === "kits"
            ? "bg-white text-[#36a4f2] shadow-sm"
            : "text-slate-500 hover:text-slate-700"
            }`}
        >
          <FolderOpen className="w-4 h-4 shrink-0" />
          액션 키트
        </button>
        <button
          onClick={() => handleDomainChange("laws")}
          className={`flex items-center justify-center gap-1.5 md:gap-2 flex-1 md:flex-none py-2.5 px-4 md:px-6 rounded-xl text-sm font-bold whitespace-nowrap transition-all ${activeDomain === "laws"
            ? "bg-white text-[#36a4f2] shadow-sm"
            : "text-slate-500 hover:text-slate-700"
            }`}
        >
          <Scale className="w-4 h-4 shrink-0" />
          법령 가이드
        </button>
        <button
          onClick={() => handleDomainChange("stats")}
          className={`flex items-center justify-center gap-1.5 md:gap-2 flex-1 md:flex-none py-2.5 px-4 md:px-6 rounded-xl text-sm font-bold whitespace-nowrap transition-all ${activeDomain === "stats"
            ? "bg-white text-[#36a4f2] shadow-sm"
            : "text-slate-500 hover:text-slate-700"
            }`}
        >
          <BarChart3 className="w-4 h-4 shrink-0" />
          통계 대시보드
        </button>
      </div>

      {activeDomain === "stats" ? (
        <OpsActionKitStatsDashboard items={items} />
      ) : (
        <>
          {/* Category Tabs (Sub Level) */}
          <div className="flex gap-2 border-b border-slate-200 pb-2 overflow-x-auto items-center">
            {filteredCategories.map((cat) => (
              <div key={cat.id} className="group relative flex items-center">
                <button
                  onClick={() => setActiveCategory(cat.id)}
                  onDoubleClick={() => {
                    setEditingCategory(cat);
                    setIsCategoryModalOpen(true);
                  }}
                  className={`px-4 py-2 font-bold text-sm rounded-t-xl transition-colors ${activeCategory === cat.id
                    ? "bg-slate-100 text-[#36a4f2] border-b-2 border-[#36a4f2]"
                    : "text-slate-500 hover:bg-slate-50"
                    }`}
                  title="더블 클릭하여 수정"
                >
                  {cat.title}
                </button>
                <button
                  title="카테고리 수정/삭제"
                  onClick={() => { setEditingCategory(cat); setIsCategoryModalOpen(true); }}
                  className="opacity-0 group-hover:opacity-100 absolute right-1 top-1 text-slate-400 hover:text-[#36a4f2] bg-white rounded-full p-0.5"
                >
                  <Settings className="w-3 h-3" />
                </button>
              </div>
            ))}
            <button
              title="새 카테고리 추가"
              onClick={() => { setEditingCategory(null); setIsCategoryModalOpen(true); }}
              className="ml-2 w-8 h-8 rounded-full border border-dashed border-slate-300 flex items-center justify-center text-slate-400 hover:text-[#36a4f2] hover:border-[#36a4f2] transition-colors"
            >
              <Plus className="w-5 h-5" />
            </button>
          </div>

          <Card className="shadow-sm border-slate-200">
            <div className="p-4 border-b border-slate-100 flex justify-between">
              <div className="relative w-64">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                <input
                  type="text"
                  placeholder="항목 검색..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-9 pr-4 py-1.5 text-sm border-slate-200 rounded-lg focus:ring-[#36a4f2]/20 outline-none border"
                />
              </div>
              <div className="text-sm font-semibold text-slate-500 flex items-center">
                총 {filteredItems.length}개 항목
              </div>
            </div>
            <CardContent className="p-0">
              {loading ? (
                <div className="py-20 flex justify-center items-center text-slate-400">
                  <Loader2 className="w-8 h-8 animate-spin" />
                </div>
              ) : filteredItems.length === 0 ? (
                <div className="py-20 text-center text-slate-400">
                  <FolderOpen className="w-12 h-12 mx-auto mb-4 opacity-20" />
                  <p className="text-sm font-bold">
                    {searchQuery ? "검색 결과가 없습니다." : "이 카테고리에는 아직 항목이 없습니다."}
                  </p>
                </div>
              ) : (
                <div className="w-full">
                  <table className="w-full text-left text-sm whitespace-nowrap">
                    <thead className="bg-slate-50 text-slate-500 font-semibold border-b border-slate-100">
                      <tr>
                        <th className="px-3 py-3 w-8"></th>
                        <th className="px-6 py-3">상태</th>
                        <th className="px-6 py-3 w-1/3">제목</th>
                        <th className="px-6 py-3">종류/태그</th>
                        <th className="px-6 py-3">첨부버전</th>
                        <th className="px-6 py-3">순서</th>
                        <th className="px-6 py-3 text-right">관리</th>
                      </tr>
                    </thead>
                    <DragDropContext onDragEnd={handleDragEnd}>
                      <Droppable droppableId="items_list">
                        {(provided) => (
                          <tbody
                            className="divide-y divide-slate-100"
                            {...provided.droppableProps}
                            ref={provided.innerRef}
                          >
                            {filteredItems.map((item, index) => (
                              <Draggable key={item.id.toString()} draggableId={item.id.toString()} index={index} isDragDisabled={!!searchQuery}>
                                {(provided, snapshot) => (
                                  <tr
                                    ref={provided.innerRef}
                                    {...provided.draggableProps}
                                    className={`transition-colors ${snapshot.isDragging ? 'bg-white shadow-xl ring-1 ring-[#36a4f2]/20' : 'hover:bg-slate-50'}`}
                                  >
                                    <td className="px-3 py-4" {...provided.dragHandleProps}>
                                      <GripVertical className="w-4 h-4 text-slate-300 hover:text-slate-500 cursor-grab active:cursor-grabbing" />
                                    </td>
                                    <td className="px-6 py-4">
                                      <Badge className={`border-none ${item.is_active ? 'bg-emerald-100 text-emerald-600' : 'bg-slate-100 text-slate-400'}`}>
                                        {item.is_active ? '게시중' : '숨김'}
                                      </Badge>
                                    </td>
                                    <td className="px-6 py-4">
                                      <div className="font-bold flex items-center gap-2">
                                        {item.name}
                                        {!item.is_active && <Badge variant="secondary" className="text-xs bg-slate-100 text-slate-500 hover:bg-slate-200 border-none px-1.5 py-0">미공개</Badge>}
                                        {(() => {
                                          let isOutdated = false;
                                          if (item.updated_at) {
                                            const updatedDate = new Date(item.updated_at);
                                            const now = new Date();
                                            const diffTime = Math.abs(now.getTime() - updatedDate.getTime());
                                            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                                            if (diffDays > 365) isOutdated = true;
                                          }
                                          if (isOutdated) {
                                            return <Badge variant="destructive" className="text-[10px] bg-red-50 text-red-600 border border-red-200 hover:bg-red-100 px-1.5 py-0 shadow-none"><AlertTriangle className="w-3 h-3 mr-1" />갱신 필요</Badge>
                                          }
                                          return null;
                                        })()}
                                      </div>
                                      <p className="text-xs text-slate-400 line-clamp-1 mt-0.5">{item.summary}</p>
                                    </td>
                                    <td className="px-6 py-4">
                                      <Badge variant="outline" className="text-[10px] text-slate-500">{item.type || item.ext || item.file_type || "유형없음"}</Badge>
                                    </td>
                                    <td className="px-6 py-4 text-xs font-semibold text-slate-500">
                                      v{item.files?.length ? item.files[0].version : "1"} (최신)
                                    </td>
                                    <td className="px-6 py-4 text-xs text-slate-500">
                                      {item.sort_order || 0}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                      <div className="flex justify-end gap-2">
                                        <Button
                                          variant="outline"
                                          size="icon"
                                          onClick={() => setEditingItem(item)}
                                          className="w-8 h-8 rounded-md text-slate-400 hover:text-[#36a4f2]"
                                        >
                                          <Edit3 className="w-4 h-4" />
                                        </Button>
                                        <Button variant="outline" size="icon" className="w-8 h-8 rounded-md text-slate-400 hover:text-red-500" onClick={() => handleDelete(item)}>
                                          <Trash2 className="w-4 h-4" />
                                        </Button>
                                      </div>
                                    </td>
                                  </tr>
                                )}
                              </Draggable>
                            ))}
                            {provided.placeholder}
                          </tbody>
                        )}
                      </Droppable>
                    </DragDropContext>
                  </table>
                </div>
              )}
            </CardContent>
          </Card>

          {editingItem && (
            <ActionKitEditModal
              item={editingItem}
              isOpen={!!editingItem}
              onClose={() => setEditingItem(null)}
              onSaved={() => {
                if (activeCategory) loadItems(activeCategory);
                fetchSummary().then(setSummary).catch(console.error);
              }}
            />
          )}

          {isCreating && activeCategory && (
            <ActionKitEditModal
              item={{ category_id: activeCategory, isNew: true }}
              isOpen={isCreating}
              onClose={() => setIsCreating(false)}
              onSaved={() => {
                if (activeCategory) loadItems(activeCategory);
                fetchSummary().then(setSummary).catch(console.error);
              }}
            />
          )}

          {(isCategoryModalOpen) && (
            <CategoryEditModal
              isOpen={isCategoryModalOpen}
              onClose={() => setIsCategoryModalOpen(false)}
              onSaved={handleCategorySaved}
              category={editingCategory}
              activeDomain={activeDomain}
            />
          )}
        </>
      )}
    </div>
  );
}
